            // 4. SAMSUNG GALAXY
            else if (/SamsungBrowser|SAMSUNG|\b(SM|GT|SCH|SPH|SGH)-[A-Z0-9]+/i.test(ua) || (navigator.userAgentData && navigator.userAgentData.brands && navigator.userAgentData.brands.some(b => /Samsung/i.test(b.brand)))) {
                brand = 'samsung';
