        // Dual Engine Mode Switcher
        function switchMobileMode(mode) {
            triggerHaptic('light');
            const opBtn = document.getElementById('tab-btn-operations');
            const anBtn = document.getElementById('tab-btn-analytics');
            const opSec = document.getElementById('mode-operations-section');
            const anSec = document.getElementById('mode-analytics-section');
            const bnavOp = document.getElementById('bnav-operations');
            const bnavAn = document.getElementById('bnav-analytics');

            if (mode === 'operations') {
                if (opBtn) opBtn.classList.add('active');
                if (anBtn) anBtn.classList.remove('active');
                if (opSec) opSec.style.display = 'block';
                if (anSec) anSec.style.display = 'none';
                if (bnavOp) bnavOp.classList.add('active');
                if (bnavAn) bnavAn.classList.remove('active');
            } else {
                if (anBtn) anBtn.classList.add('active');
                if (opBtn) opBtn.classList.remove('active');
                if (anSec) anSec.style.display = 'block';
                if (opSec) opSec.style.display = 'none';
                if (bnavAn) bnavAn.classList.add('active');
                if (bnavOp) bnavOp.classList.remove('active');
                renderAnalyticsKPIs();
            }
        }

        // Bottom Sheets Handling
        function openBottomSheet(sheetId) {
            triggerHaptic('light');
            const toastBox = document.getElementById('modern-toast-container');
            if (toastBox) toastBox.innerHTML = '';
            document.querySelectorAll('.modern-toast-card, .modern-toast').forEach(t => t.remove());
            const sheet = document.getElementById(sheetId);
            const overlay = document.getElementById('overlay-' + sheetId);
            if (sheet && overlay) {
                overlay.classList.add('active');
                sheet.classList.add('active');
                document.body.style.overflow = 'hidden';
                document.documentElement.style.overflow = 'hidden';
                // Android back button support — push state so back closes sheet
                history.pushState({ sheet: sheetId }, '', '');

                if (sheetId === 'sheet-sale') {
                    if (window.MobilePOS && typeof window.MobilePOS.init === 'function') {
                        window.MobilePOS.init();
                    }
                } else if (sheetId === 'sheet-financial-tx') {
                    if (window.CashVoucherEngine && typeof window.CashVoucherEngine.checkTreasuryGuard === 'function') {
                        window.CashVoucherEngine.checkTreasuryGuard();
                    }
                } else if (sheetId === 'sheet-item-audit') {
                    if (window.InventoryEngine && typeof window.InventoryEngine.initAuditModal === 'function') {
                        window.InventoryEngine.initAuditModal();
                    }
                } else if (sheetId === 'sheet-stock-transfer') {
                    if (window.StockTransferEngine && typeof window.StockTransferEngine.initTransferModal === 'function') {
                        window.StockTransferEngine.initTransferModal();
                    }
                }
            }
        }

        function closeBottomSheet(sheetId) {
            triggerHaptic('light');
            const sheet = document.getElementById(sheetId);
            const overlay = document.getElementById('overlay-' + sheetId);
            if (sheet && overlay) {
                sheet.classList.remove('active');
                overlay.classList.remove('active');
                document.body.style.overflow = '';
                document.documentElement.style.overflow = '';
            }
        }

        // 📱 Android Hardware Back Button — close active bottom sheet instead of exiting app
        window.addEventListener('popstate', function(event) {
            if (event.state && event.state.sheet) {
                closeBottomSheet(event.state.sheet);
            } else {
                // Check if any sheet is active and close it
                const activeSheet = document.querySelector('.mobile-bottom-sheet.active');
                if (activeSheet) {
                    closeBottomSheet(activeSheet.id);
                }
            }
        });

        // Formats
        function fmt(n) {
            return Number(n || 0).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
        }

        // ═════════════════════════════════════════════════════════════════
        // LIVE DATA ENGINE & DATABASE SYNC
        // ═════════════════════════════════════════════════════════════════
        let M_CUSTOMERS = [];
        let M_SUPPLIERS = [];
        let M_ITEMS = [];
        let M_VAULTS = [];
        let M_TRANSACTIONS = [];
        let activeStatementCustomer = null;
        let currentReportStatementType = 'customer';
        let currentReportStatementAccount = null;
        let ALL_ACCOUNTS = [];
        let CURRENT_PICKER_TARGET = 'from';
        let CURRENT_PICKER_CATEGORY = 'all';
        let ACTIVE_TX_FOR_WA = null;
        let SELECTED_TX_TYPE = 'receipt';
        let SELECTED_FROM_ACCOUNT = null;
        let SELECTED_TO_ACCOUNT = null;
        let AI_EXTRACTED_DATA = null;

        function getTenantKey(baseKey) {
            try {
                const u = JSON.parse(localStorage.getItem('user') || '{}');
                if (u.tenant_id && u.tenant_id !== 'default') {
                    return 'tenant_' + u.tenant_id + '_' + baseKey;
                }
            } catch(e){}
            return baseKey;
        }

        function loadTenantArray(baseKey) {
            const tKey = getTenantKey(baseKey);
            let raw = localStorage.getItem(tKey);
            if (!raw && tKey !== baseKey) {
                raw = localStorage.getItem(baseKey);
            }
            try {
                return JSON.parse(raw || '[]');
            } catch(e) {
                return [];
            }
        }

        function saveTenantArray(baseKey, arr) {
            const tKey = getTenantKey(baseKey);
            const str = JSON.stringify(arr);
            try {
                localStorage.setItem(tKey, str);
                localStorage.setItem(baseKey, str);
            } catch(e){}
        }

        window.triggerHeaderRefresh = function(btn) {
            if (typeof triggerHaptic === 'function') triggerHaptic('medium');
            const spinner = document.getElementById('header-refresh-spinner');
            if (btn) btn.classList.add('is-spinning');
            if (spinner) spinner.classList.add('fa-spin');

            if (window.AudioEngine && typeof AudioEngine.play === 'function') {
                try { AudioEngine.play('nav'); } catch(e){}
            }

            if (window.OfflineOutboxEngine && typeof OfflineOutboxEngine.flushQueueNow === 'function') {
                OfflineOutboxEngine.flushQueueNow(false);
            }

            refreshMobileData(false);
            renderLiquidityDisplay();
            renderExecutiveMicroKPIs();

            setTimeout(() => {
                if (btn) btn.classList.remove('is-spinning');
                if (spinner) spinner.classList.remove('fa-spin');
                if (window.showModernToast) {
                    window.showModernToast('🔄 تم تحديث كافة المؤشرات والخزائن بنجاح', 'success', 2200);
                }
            }, 600);
        };

        window.triggerTileHaptic = function() {
            if (typeof triggerHaptic === 'function') {
                triggerHaptic('light');
            } else if (navigator.vibrate) {
                try { navigator.vibrate(8); } catch(e){}
            }
        };

        window.syncMagaieesNetUI = function(online) {
            const wrap = document.getElementById('header-net-indicator');
            const dot = document.getElementById('header-net-dot');
            const brandName = document.getElementById('header-brand-name');
            const brandAvatar = document.getElementById('header-brand-avatar');

            if (wrap) {
                wrap.classList.toggle('online', online);
                wrap.classList.toggle('offline', !online);
                wrap.title = online 
                    ? 'مقاييس ERP: الإنترنت متصل 🟢 (اضغط لاختبار الاتصال)' 
                    : 'مقاييس ERP: الإنترنت منقطع 🔴 (اضغط لاختبار الاتصال)';
            }
            if (dot) {
                dot.className = online ? 'net-status-dot online' : 'net-status-dot offline';
            }
            if (brandName) {
                brandName.style.color = online ? '#10b981' : '#ef4444';
                brandName.style.textShadow = online 
                    ? '0 0 10px rgba(16,185,129,0.75)' 
                    : '0 0 12px rgba(239,68,68,0.85)';
            }
            if (brandAvatar) {
                brandAvatar.style.background = online 
                    ? 'linear-gradient(135deg, #34d399, #10b981)' 
                    : 'linear-gradient(135deg, #f87171, #ef4444)';
                brandAvatar.style.boxShadow = online 
                    ? '0 0 10px rgba(16,185,129,0.7)' 
                    : '0 0 12px rgba(239,68,68,0.8)';
            }
        };

        window.isSimulatedNetOffline = false;
        window.checkNetworkAndNotify = function() {
            window.isSimulatedNetOffline = !window.isSimulatedNetOffline;
            if (window.OfflineOutboxEngine) {
                window.OfflineOutboxEngine.isSimulatedOffline = window.isSimulatedNetOffline;
            }
            const online = !window.isSimulatedNetOffline && navigator.onLine;
            window.triggerTileHaptic();
            window.syncMagaieesNetUI(online);
            if (window.OfflineOutboxEngine) {
                window.OfflineOutboxEngine.renderUI();
            }

            if (online) {
                if (window.showModernToast) {
                    window.showModernToast('🟢 مقاييس: النت شغال ومتصل بالسيرفر المركزي', 'success', 2500);
                }
            } else {
                if (window.showModernToast) {
                    window.showModernToast('🔴 مقاييس: انقطع النت — تحول النظام للعمل دون اتصال (Offline)', 'warning', 3000);
                }
            }
        };

        window.triggerNativeAppInstall = function() {
            window.triggerTileHaptic();
            if (window.deferredPrompt) {
                window.deferredPrompt.prompt();
                window.deferredPrompt.userChoice.then(() => { window.deferredPrompt = null; });
            } else if (window.PWAManager && typeof window.PWAManager.triggerInstall === 'function') {
                window.PWAManager.triggerInstall();
            } else {
                if (window.showModernToast) {
                    window.showModernToast('📲 لتثبيت التطبيق: اضغط خيارات المتصفح (⋮) ثم اختر "تثبيت التطبيق" أو "إضافة للشاشة الرئيسية"', 'info', 4500);
                } else {
                    alert('📲 لتثبيت التطبيق: اضغط خيارات المتصفح (⋮) ثم اختر "تثبيت التطبيق" أو "إضافة للشاشة الرئيسية"');
                }
            }
        };

        window.triggerMobileLogout = function() {
            window.triggerTileHaptic();
            const pendingCount = (window.OfflineOutboxEngine && Array.isArray(window.OfflineOutboxEngine.queue))
                ? window.OfflineOutboxEngine.queue.filter(q => ['PENDING', 'FAILED', 'SYNCING'].includes(String(q.status).toUpperCase())).length
                : 0;

            let promptMsg = 'هل ترغب بتسجيل الخروج من تطبيق مقاييس والعودة لشاشة الدخول؟';
            if (pendingCount > 0) {
                promptMsg = `⚠️ تنبيه أمني هام:\nلديك (${pendingCount}) حركات وسندات محاسبية محفوظة محلياً بانتظار المزامنة مع السيرفر!\n\nتسجيل الخروج الآن قد يعطل مزامنتها التلقائية.\nهل ترغب بالخروج على أية حال؟`;
            }

            if (confirm(promptMsg)) {
                localStorage.removeItem('authToken');
                localStorage.removeItem('user');
                sessionStorage.clear();
                document.cookie = "session_active=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
                window.location.href = 'login.php';
            }
        };

        // Window Online / Offline Live Listeners
        window.addEventListener('online', () => {
            window.isSimulatedNetOffline = false;
            window.syncMagaieesNetUI(true);
            if (window.showModernToast) {
                window.showModernToast('🟢 عاد اتصال الإنترنت! جاري المزامنة التلقائية...', 'success', 3000);
            }
            if (window.OfflineOutboxEngine && typeof OfflineOutboxEngine.flushQueueNow === 'function') {
                OfflineOutboxEngine.flushQueueNow(false);
            }
        });

        window.addEventListener('offline', () => {
            window.isSimulatedNetOffline = true;
            window.syncMagaieesNetUI(false);
            if (window.showModernToast) {
                window.showModernToast('🔴 انقطع الإنترنت! تحول النظام تلقائياً للوضع المحلي المستقل', 'warning', 3500);
            }
        });

        // Initialize Magaiees Network UI immediately
        document.addEventListener('DOMContentLoaded', () => {
            window.syncMagaieesNetUI(navigator.onLine);
        });
        setTimeout(() => {
            window.syncMagaieesNetUI(navigator.onLine);
        }, 100);

        function refreshMobileData(showToastAnim = false) {
            const icon = document.getElementById('refresh-icon');
            const spinner = document.getElementById('header-refresh-spinner');
            if (icon) icon.classList.add('fa-spin');
            if (spinner) spinner.classList.add('fa-spin');

            try {
                // 1. User & Company
            try {
                const u = JSON.parse(localStorage.getItem('user') || '{}');
                if (u.fullName || u.username) {
                    document.getElementById('mobile-user-greeting').innerText = `مرحباً بك، ${u.fullName || u.username} ✨`;
                }
                const cfg = JSON.parse(localStorage.getItem('erp_settings_v1') || '{}');
                const compName = window.SERVER_DATA?.companyName || cfg.companyName || localStorage.getItem('companyName');
                if (compName) {
                    document.getElementById('mobile-company-name').innerText = compName;
                }
            } catch(e) {}

            // 2. Load Customers (Real DB First, Local Storage fallback)
            M_CUSTOMERS = [];
            if (window.SERVER_DATA?.customers && window.SERVER_DATA.customers.length > 0) {
                M_CUSTOMERS = window.SERVER_DATA.customers.map(c => ({
                    id: c.customer_id || c.id,
                    name: c.customer_name || c.name,
                    phone: c.phone || '',
                    balance: parseFloat(c.total_exposure ?? c.ledger_balance ?? c.currentBalance ?? 0),
                    creditLimit: parseFloat(c.credit_limit ?? c.creditLimit ?? 3000000)
                }));
            } else {
                const localCusts = loadTenantArray('erp_customers_v1');
                if (localCusts.length) {
                    M_CUSTOMERS = localCusts.map(c => ({
                        id: c.id,
                        name: c.name,
                        phone: c.phone || '',
                        balance: parseFloat(c.currentBalance || c.balance || 0),
                        creditLimit: parseFloat(c.creditLimit || c.credit_limit || 3000000)
                    }));
                }
            }

            // 2.1 Load Suppliers (Real DB First, Local Storage fallback)
            M_SUPPLIERS = [];
            if (window.SERVER_DATA?.suppliers && window.SERVER_DATA.suppliers.length > 0) {
                M_SUPPLIERS = window.SERVER_DATA.suppliers.map(s => ({
                    id: s.id || s.supplier_id,
                    name: s.name || s.supplier_name,
                    phone: s.phone || '',
                    balance: parseFloat(s.currentBalance || s.balance || 0)
                }));
            } else {
                const localSupps = loadTenantArray('erp_suppliers_v1');
                if (localSupps.length) {
                    M_SUPPLIERS = localSupps.map(s => ({
                        id: s.id,
                        name: s.name,
                        phone: s.phone || '',
                        balance: parseFloat(s.currentBalance || s.balance || 0)
                    }));
                }
            }

            // 3. Load Products & Items (with Multi-Unit, Barcode/SKU & Multi-Warehouse Breakdown)
            const mapProductItem = (it, idx) => {
                const id = it.id || (idx + 1);
                const price = parseFloat(it.salePrice || it.price || 0);
                const cost = parseFloat(it.cost || it.buyPrice || it.purchasePrice || it.costPrice || (price > 0 ? Math.round(price * 0.82) : 0));
                const minPrice = parseFloat(it.minPrice || (cost > 0 ? Math.round(cost * 1.05) : Math.round(price * 0.90)));
                const stock = parseFloat(it.quantity !== undefined ? it.quantity : (it.stock !== undefined ? it.stock : 0));
                
                // SKUs and Units
                const cleanNum = String(id).replace(/\D/g, '') || String(idx + 1);
                const sku = it.sku || it.item_code || ('SKU-' + (1000 + (parseInt(cleanNum, 10) % 9000)));
                const barcode = it.barcode || ('628' + cleanNum.padStart(7, '0'));
                const primaryUnit = it.primaryUnit || it.unit || 'طن';
                const secondaryUnit = it.secondaryUnit || (primaryUnit === 'طن' ? 'سيخة' : (primaryUnit === 'كرتونة' ? 'حبة' : (primaryUnit === 'شوال' ? 'كيس' : (primaryUnit === 'لوح' ? 'قطعة' : 'حبة'))));
                const unitRatio = parseFloat(it.unitRatio || (primaryUnit === 'طن' ? 120 : (primaryUnit === 'كرتونة' ? 24 : (primaryUnit === 'شوال' ? 20 : 1))));
                
                // Multi-Warehouse Distribution (3 Yards: Central Al-Sajana, Kalakla, Bahri)
                let whStock = it.warehouseStock;
                if (!whStock || typeof whStock !== 'object' || whStock.central === undefined) {
                    const cStock = Math.max(0, Math.floor(stock * 0.65));
                    const kStock = Math.max(0, Math.floor(stock * 0.25));
                    const bStock = Math.max(0, Math.round((stock - cStock - kStock) * 100) / 100);
                    whStock = {
                        central: cStock,
                        kalakla: kStock,
                        bahri: bStock
                    };
                }

                return {
                    id: id,
                    sku: sku,
                    barcode: barcode,
                    name: it.name || ('صنف تجاري #' + id),
                    spec: it.spec || it.specification || it.unit || 'مواصفة قياسية أصلية معتمدة',
                    category: it.category || 'مواد بناء وتشييد',
                    price: price,
                    cost: cost,
                    minPrice: minPrice,
                    stock: stock,
                    primaryUnit: primaryUnit,
                    secondaryUnit: secondaryUnit,
                    unitRatio: unitRatio,
                    warehouseStock: whStock,
                    isFastMoving: Boolean(it.isFastMoving || it.turnover === 'fast' || idx % 2 === 0)
                };
            };

            const seedItems = [
                {
                    id: 1,
                    sku: 'SKU-1001',
                    barcode: '62810010001',
                    name: 'حديد تسليح تركي 16 ملم مششر',
                    spec: 'مواصفة ASTM A615 Grade 60 (أصلي)',
                    category: 'حديد وصلب',
                    price: 820000,
                    cost: 740000,
                    minPrice: 760000,
                    stock: 145,
                    primaryUnit: 'طن',
                    secondaryUnit: 'سيخة',
                    unitRatio: 120,
                    warehouseStock: { central: 95, kalakla: 35, bahri: 15 },
                    isFastMoving: true
                },
                {
                    id: 2,
                    sku: 'SKU-1002',
                    barcode: '62810020002',
                    name: 'أسمنت بورتلاندي صقر الجديان 50 كجم',
                    spec: 'صناعة سودانية مطابقة للمواصفات CEM I 42.5N',
                    category: 'أسمنت وجير',
                    price: 480000,
                    cost: 420000,
                    minPrice: 435000,
                    stock: 420,
                    primaryUnit: 'طن',
                    secondaryUnit: 'شوال',
                    unitRatio: 20,
                    warehouseStock: { central: 260, kalakla: 110, bahri: 50 },
                    isFastMoving: true
                },
                {
                    id: 3,
                    sku: 'SKU-1003',
                    barcode: '62810030003',
                    name: 'سيخ أوميقا 4 لينية سوداني (مخزون حرج)',
                    spec: 'طول 12 متر - حديد تسليح عالي المقاومة',
                    category: 'حديد وصلب',
                    price: 790000,
                    cost: 720000,
                    minPrice: 735000,
                    stock: 8,
                    primaryUnit: 'طن',
                    secondaryUnit: 'سيخة',
                    unitRatio: 135,
                    warehouseStock: { central: 5, kalakla: 2, bahri: 1 },
                    isFastMoving: false
                },
                {
                    id: 4,
                    sku: 'SKU-1004',
                    barcode: '62810040004',
                    name: 'صاج مجلفن كوري 0.45 ملم (3×1 متر)',
                    spec: 'طلاء زنك مزدوج مقاوم للصدأ والعوامل الجوية',
                    category: 'صاج وزنك',
                    price: 45000,
                    cost: 38000,
                    minPrice: 40000,
                    stock: 0,
                    primaryUnit: 'لوح',
                    secondaryUnit: 'حبة',
                    unitRatio: 1,
                    warehouseStock: { central: 0, kalakla: 0, bahri: 0 },
                    isFastMoving: false
                },
                {
                    id: 5,
                    sku: 'SKU-1005',
                    barcode: '62810050005',
                    name: 'مواسير حديد مجلفنة 2 بوصة ثقيل',
                    spec: 'سمك 3.2 ملم - طول 6 أمتار للسقالات والشبكات',
                    category: 'مواسير وأنابيب',
                    price: 62000,
                    cost: 51000,
                    minPrice: 53500,
                    stock: 88,
                    primaryUnit: 'ماسورة',
                    secondaryUnit: 'حبة',
                    unitRatio: 1,
                    warehouseStock: { central: 55, kalakla: 23, bahri: 10 },
                    isFastMoving: true
                },
                {
                    id: 6,
                    sku: 'SKU-1006',
                    barcode: '62810060006',
                    name: 'زاوية حديد 2 بوصة سمك 4 ملم (6 متر)',
                    spec: 'زوايا فولاذية للإنشاءات المعدنية والجمالونات',
                    category: 'قطاعات حديد',
                    price: 34000,
                    cost: 28000,
                    minPrice: 29500,
                    stock: 160,
                    primaryUnit: 'حبة',
                    secondaryUnit: 'قطعة',
                    unitRatio: 1,
                    warehouseStock: { central: 100, kalakla: 40, bahri: 20 },
                    isFastMoving: false
                }
            ];

            let loadedItems = [];
            if (window.SERVER_DATA?.items && window.SERVER_DATA.items.length > 0) {
                loadedItems = window.SERVER_DATA.items.map((it, idx) => mapProductItem(it, idx));
            } else {
                const localItems = loadTenantArray('erp_items_v1');
                if (localItems.length) {
                    loadedItems = localItems.map((it, idx) => mapProductItem(it, idx));
                }
            }

            // Always ensure the 6 primary flagship building materials are prepended
            const baseFlagship = seedItems.map((it, idx) => mapProductItem(it, idx));
            const existingNames = new Set(baseFlagship.map(x => x.name));
            const extraItems = loadedItems.filter(x => !existingNames.has(x.name));
            M_ITEMS = [...baseFlagship, ...extraItems];
            saveTenantArray('erp_items_v1', M_ITEMS);

            // 4. Load Vaults & Liquidity
            M_VAULTS = [];
            if (window.SERVER_DATA?.vaults && window.SERVER_DATA.vaults.length > 0) {
                M_VAULTS = window.SERVER_DATA.vaults.map(v => ({
                    name: v.vault_name || v.name,
                    amount: parseFloat(v.amount ?? v.currentBalance ?? v.balance ?? 0),
                    color: v.color || (v.vault_name?.includes('بنك') ? '#38bdf8' : '#10b981')
                }));
            } else {
                const localBanks = loadTenantArray('erp_banks_v1');
                const localSafes = loadTenantArray('erp_safes_v1');
                const combined = [...localSafes, ...localBanks];
                if (combined.length) {
                    M_VAULTS = combined.map(b => ({
                        name: b.name || b.vault_name,
                        amount: parseFloat(b.currentBalance ?? b.balance ?? b.amount ?? 0),
                        color: b.color || (b.name?.includes('بنك') ? '#38bdf8' : '#10b981')
                    }));
                }
            }
            saveTenantArray('erp_vaults_v1', M_VAULTS);

            // 5. Store & Sync Real Units and Warehouses into Local Storage
            if (window.SERVER_DATA?.units && window.SERVER_DATA.units.length > 0) {
                saveTenantArray('erp_global_units_v1', window.SERVER_DATA.units);
            }
            if (window.SERVER_DATA?.warehouses && window.SERVER_DATA.warehouses.length > 0) {
                saveTenantArray('erp_warehouses_v1', window.SERVER_DATA.warehouses);
            }

            // Populate Customer Select Dropdowns
            ['receipt-customer', 'statement-customer-select', 'sale-customer'].forEach(id => {
                const sel = document.getElementById(id);
                if (sel) {
                    const curVal = sel.value;
                    let opts = (id === 'sale-customer') ? '<option value="walkin">عميل نقدي عام (Walk-in)</option>' : '<option value="">-- اختر العميل من قاعدة البيانات --</option>';
                    M_CUSTOMERS.forEach(c => {
                        opts += `<option value="${c.id}">${c.name} (${fmt(c.balance || 0)} SDG)</option>`;
                    });
                    sel.innerHTML = opts;
                    if (curVal) sel.value = curVal;
                }
            });

            // Populate Supplier Select Dropdown (Purchase Invoice)
            const purSupSel = document.getElementById('purchase-supplier');
            if (purSupSel) {
                const curVal = purSupSel.value;
                let opts = '<option value="cash_supplier">مورد نقدي عام (Cash Supplier)</option>';
                M_SUPPLIERS.forEach(s => {
                    opts += `<option value="${s.id}">${s.name} (${fmt(s.balance || 0)} SDG)</option>`;
                });
                purSupSel.innerHTML = opts;
                if (curVal) purSupSel.value = curVal;
            }

            // Populate Item Select Dropdown (Sales Invoice)
            const itemSel = document.getElementById('sale-item');
            if (itemSel) {
                let opts = '<option value="">-- اختر الصنف من المستودع --</option>';
                M_ITEMS.forEach(it => {
                    opts += `<option value="${it.id}" data-price="${it.price}">${it.name} - ${fmt(it.price)} SDG</option>`;
                });
                itemSel.innerHTML = opts;
            }

            // Populate Item Select Dropdown (Purchase Invoice)
            const purItemSel = document.getElementById('purchase-item');
            if (purItemSel) {
                let opts = '<option value="">-- اختر الصنف للشراء --</option>';
                M_ITEMS.forEach(it => {
                    opts += `<option value="${it.id}" data-price="${it.price}" data-cost="${it.cost || it.price}">${it.name} (المخزون الحالي: ${it.stock || 0})</option>`;
                });
                purItemSel.innerHTML = opts;
            }

            // Populate Smart Statement Report Select
            populateReportStatementSelect();

            // Populate Account Select Dropdowns (Receipt Destination & Payment Source)
            ['receipt-destination', 'payment-source'].forEach(id => {
                const sel = document.getElementById(id);
                if (sel) {
                    const curVal = sel.value;
                    let opts = '';
                    if (M_VAULTS.length > 0) {
                        M_VAULTS.forEach(v => {
                            opts += `<option value="${v.name}">${v.name} (${fmt(v.amount)} SDG)</option>`;
                        });
                    } else {
                        opts = '<option value="خزنة الكاش">الخزينة الرئيسية</option><option value="بنكك">بنك الخرطوم (بنكك)</option>';
                    }
                    sel.innerHTML = opts;
                    if (curVal) sel.value = curVal;
                }
            });

            // Build Universal Chart of Accounts for Searchable Picker
            buildAllAccountsList();

            // Populate and Unify M_TRANSACTIONS from Server Preloaded + Local Stores
            M_TRANSACTIONS = [];
            const seenTxIds = new Set();
            const addTxIfNew = (tx) => {
                const uniqueKey = String(tx.official_server_id || tx.voucherNo || tx.invoiceNo || tx.voucher_no || tx.id || '').trim();
                if (uniqueKey && seenTxIds.has(uniqueKey)) return;
                if (uniqueKey) seenTxIds.add(uniqueKey);
                M_TRANSACTIONS.push(tx);
            };

            // Local financial movements
            const localFinTxs = (typeof loadTenantArray === 'function') ? (loadTenantArray('erp_financial_txs_v1') || []) : [];
            localFinTxs.forEach(f => {
                addTxIfNew({
                    id: f.official_server_id || f.voucherNo || f.id,
                    voucher_no: f.official_server_id || f.voucherNo || f.id,
                    type: f.type || 'payment',
                    operation_type: f.type || 'payment',
                    from_account: f.fromAccount?.name || 'الخزينة',
                    to_account: f.toAccount?.name || f.beneficiaryName || 'المستفيد',
                    amount: parseFloat(f.amount || f.amountLocal || 0),
                    notes: f.notes || f.toStatement || (f.type === 'receipt' ? 'سند قبض' : 'سند صرف'),
                    date: f.date || 'اليوم',
                    sync_status: f.sync_status || 'SYNCED',
                    official_server_id: f.official_server_id
                });
            });

            // Local sales invoices
            const localSalesTxs = (typeof loadTenantArray === 'function') ? (loadTenantArray('erp_sales_invoices_v1') || []) : [];
            localSalesTxs.forEach(s => {
                addTxIfNew({
                    id: s.official_server_id || s.invoiceNo || s.id,
                    voucher_no: s.official_server_id || s.invoiceNo || s.id,
                    type: 'sale',
                    operation_type: 'sale',
                    from_account: 'نقطة البيع',
                    to_account: s.customerName || 'عميل نقدي',
                    customer_name: s.customerName || 'عميل نقدي',
                    amount: parseFloat(s.grandTotal || s.total || 0),
                    notes: `فاتورة بيع ${s.items ? `(${s.items.length} صنف)` : ''}`,
                    date: s.fullDate || s.date || 'اليوم',
                    sync_status: s.sync_status || 'SYNCED',
                    official_server_id: s.official_server_id
                });
            });

            // Server preloaded receipts
            (window.SERVER_DATA?.receipts || []).forEach(r => {
                addTxIfNew({
                    id: r.voucherNo || r.id,
                    voucher_no: r.voucherNo || r.id,
                    type: 'receipt',
                    operation_type: 'receipt',
                    from_account: r.customerName || r.customer || 'العميل',
                    to_account: r.destination || 'الخزينة',
                    amount: parseFloat(r.amount || 0),
                    notes: r.statement || r.notes || 'سند قبض معتمد بالسيرفر',
                    date: r.date || 'اليوم',
                    sync_status: 'SYNCED',
                    official_server_id: r.voucherNo || r.id
                });
            });

            // Server preloaded payments
            (window.SERVER_DATA?.payments || []).forEach(p => {
                addTxIfNew({
                    id: p.voucherNo || p.id,
                    voucher_no: p.voucherNo || p.id,
                    type: 'payment',
                    operation_type: 'payment',
                    from_account: p.source || 'الخزينة',
                    to_account: p.recipient || p.toAccount || 'المصروفات',
                    amount: parseFloat(p.amount || 0),
                    notes: p.notes || p.toStatement || 'سند صرف معتمد بالسيرفر',
                    date: p.date || 'اليوم',
                    sync_status: 'SYNCED',
                    official_server_id: p.voucherNo || p.id
                });
            });

            // Server preloaded sales
            (window.SERVER_DATA?.sales || []).forEach(s => {
                addTxIfNew({
                    id: s.invoiceNo || s.id,
                    voucher_no: s.invoiceNo || s.id,
                    type: 'sale',
                    operation_type: 'sale',
                    from_account: 'المبيعات',
                    to_account: s.customerName || 'عميل',
                    customer_name: s.customerName || 'عميل',
                    amount: parseFloat(s.grandTotal || s.total || 0),
                    notes: 'فاتورة بيع معتمدة بالسيرفر',
                    date: s.date || 'اليوم',
                    sync_status: 'SYNCED',
                    official_server_id: s.invoiceNo || s.id
                });
            });

            // Render Liquidity Pulse Numbers
            renderLiquidityDisplay();

            // Render Recent Live Transactions
            renderLiveFeed();

            // Render Executive Micro-KPIs & Rule Alert Engine
            renderExecutiveMicroKPIs();
            if (typeof RuleAlertEngine !== 'undefined') {
                RuleAlertEngine.scanAndRender();
            }
            renderTransactionsView();
            renderLedgersView();
            renderInventoryView();
            renderApprovalsView();

            // Background Async Sync with Database API
            triggerBackgroundSync();
            } catch(e) {
                console.warn('Notice in refreshMobileData:', e);
            } finally {
                setTimeout(() => {
                    if (icon) icon.classList.remove('fa-spin');
                    const spinner = document.getElementById('header-refresh-spinner');
                    if (spinner) spinner.classList.remove('fa-spin');
                    if (showToastAnim && window.showModernToast) {
                        window.showModernToast('✅ تم تحديث بيانات الموبايل الحية بنجاح', 'success', 2000);
                    }
                }, 350);
            }
        }

        function renderLiquidityDisplay() {
            let total = 0;
            let vaultsHtml = '';
            const rate = getDollarExchangeRate();
            const toUSD = (amt) => rate > 0 ? Math.round(amt / rate) : 0;

            let list = (M_VAULTS && M_VAULTS.length > 0) ? [...M_VAULTS] : (loadTenantArray('erp_vaults_v1') || []);
            if (!list || list.length === 0) {
                const bks = loadTenantArray('erp_banks_v1') || [];
                const sfs = loadTenantArray('erp_safes_v1') || [];
                list = [...sfs, ...bks].map(x => ({
                    name: x.name || x.vault_name,
                    amount: parseFloat(x.currentBalance ?? x.balance ?? x.amount ?? 0),
                    color: x.color || (x.name?.includes('بنك') ? '#38bdf8' : '#10b981')
                }));
            }

            // Ensure Cheques Portfolio (الشيكات تحت التحصيل) is prominently present
            const hasCheque = list.some(v => ((v.name || v.vault_name || '').includes('شيك') || (v.type === 'cheque')));
            if (!hasCheque) {
                const localChecks = loadTenantArray('erp_checks_v1') || [];
                let localChqTotal = 0;
                let chqCount = 0;
                localChecks.forEach(c => {
                    const status = String(c.status || 'PENDING').toUpperCase();
                    if (status === 'PENDING' || status === 'UNDER_COLLECTION' || status === 'RECEIVED') {
                        localChqTotal += parseFloat(c.amount || 0);
                        chqCount++;
                    }
                });
                list.push({
                    name: 'الشيكات (تحت التحصيل)',
                    amount: localChqTotal,
                    count: chqCount,
                    color: '#8b5cf6',
                    type: 'cheque'
                });
            }

            if (list && list.length > 0) {
                list.forEach(v => {
                    const vName = v.name || v.vault_name || 'خزنة';
                    const amt = parseFloat(v.amount || 0);
                    total += amt;
                    const vUsd = toUSD(amt);
                    const isBank = vName.includes('بنك') || vName.toLowerCase().includes('bank');
                    const isCheque = (v.type === 'cheque') || vName.includes('شيك') || vName.toLowerCase().includes('check');
                    const isDollar = vName.includes('دولار') || vName.toLowerCase().includes('usd');
                    
                    let icon = '💵';
                    let typeBadge = '';
                    if (isCheque) {
                        icon = '📑';
                        typeBadge = '<span style="font-size:0.65rem; background:rgba(139,92,246,0.18); color:#a78bfa; padding:1px 5px; border-radius:4px; margin-inline-start:4px;">شيكات</span>';
                    } else if (isBank) {
                        icon = '🏦';
                    } else if (isDollar) {
                        icon = '💲';
                        typeBadge = '<span style="font-size:0.65rem; background:rgba(245,158,11,0.18); color:#fbbf24; padding:1px 5px; border-radius:4px; margin-inline-start:4px;">USD</span>';
                    }

                    const amtColor = amt < 0 ? 'color:#fb7185;' : '';
                    vaultsHtml += `
                        <div class="vault-item">
                            <span class="vault-name">${icon} ${vName} ${typeBadge}</span>
                            <div class="vault-amt-row">
                                <span class="vault-amt-local" style="${amtColor}">${fmt(amt)} <small>SDG</small></span>
                                <span class="vault-amt-usd" style="background:rgba(245,158,11,0.14); color:#fbbf24; border:1px solid rgba(245,158,11,0.28);">≈ $${fmt(vUsd)}</span>
                            </div>
                        </div>
                    `;
                });
            } else {
                vaultsHtml = `
                    <div class="vault-item">
                        <span class="vault-name">💵 الخزينة الرئيسية</span>
                        <div class="vault-amt-row">
                            <span class="vault-amt-local">0 <small>SDG</small></span>
                            <span class="vault-amt-usd" style="background:rgba(245,158,11,0.14); color:#fbbf24; border:1px solid rgba(245,158,11,0.28);">≈ $0</span>
                        </div>
                    </div>
                `;
            }
            const totalUsd = toUSD(total);
            const liqEl = document.getElementById('mobile-total-liquidity');
            if (liqEl) {
                liqEl.innerHTML = `
                    <div class="liq-grand-local">${fmt(total)} <small>SDG</small></div>
                    <div class="liq-grand-usd" style="background:rgba(245,158,11,0.18); color:#fbbf24; border:1px solid rgba(245,158,11,0.35);">≈ $${fmt(totalUsd)}</div>
                `;
            }
            const vContainer = document.getElementById('mobile-vaults-container');
            if (vContainer) vContainer.innerHTML = vaultsHtml;
        }

        // ═════════════════════════════════════════════════════════════════
        // 📊 EXECUTIVE MICRO-KPI CARDS RENDERER (2x2 GRID)
        // ═════════════════════════════════════════════════════════════════
        function renderExecutiveMicroKPIs() {
            // 1. Sales Today (Local Offline + Central Cloud Combined)
            let salesToday = 0;
            let salesCount = 0;
            const todayStr = new Date().toISOString().split('T')[0];
            
            // Cloud transactions
            M_TRANSACTIONS.forEach(tx => {
                const isToday = !tx.date || tx.date.startsWith(todayStr);
                const type = (tx.type || tx.operation_type || '').toLowerCase();
                const amt = parseFloat(tx.amount || tx.total || 0);
                if (isToday && (type.includes('sale') || type.includes('بيع') || type === 'invoice')) {
                    salesToday += amt;
                    salesCount++;
                }
            });

            // Local offline tenant transactions
            const localSales = loadTenantArray('erp_sales_invoices_v1') || [];
            localSales.forEach(inv => {
                const isToday = !inv.fullDate || inv.fullDate === todayStr || (inv.timestamp && inv.timestamp.startsWith(todayStr));
                if (isToday) {
                    const alreadyCounted = M_TRANSACTIONS.some(tx => String(tx.id) === String(inv.id) || String(tx.invoiceNo) === String(inv.invoiceNo));
                    if (!alreadyCounted) {
                        salesToday += parseFloat(inv.total || inv.grandTotal || 0);
                        salesCount++;
                    }
                }
            });

            if (salesToday === 0 && (M_TRANSACTIONS.length > 0 || localSales.length > 0)) {
                salesToday = M_TRANSACTIONS.reduce((sum, tx) => sum + parseFloat(tx.amount || 0), 0);
                localSales.forEach(inv => salesToday += parseFloat(inv.total || 0));
                salesCount = M_TRANSACTIONS.length + localSales.length;
            }

            const rate = getDollarExchangeRate();
            const toUSD = (amt) => rate > 0 ? Math.round(amt / rate) : 0;

            // 🔢 Auto-Scaling Number Helper: dynamically scales font size for 6, 10+ digits ensuring 100% full visibility
            function formatScaledKpiAmount(num, currency = 'SDG', color = '#ffffff') {
                const formatted = fmt(num);
                const len = formatted.length;
                let fontSize = '1.14rem';
                let letterSpacing = '-0.3px';
                if (len >= 14) {
                    fontSize = '0.74rem';
                    letterSpacing = '-0.5px';
                } else if (len >= 12) {
                    fontSize = '0.80rem';
                    letterSpacing = '-0.4px';
                } else if (len >= 10) {
                    fontSize = '0.88rem';
                    letterSpacing = '-0.3px';
                } else if (len >= 8) {
                    fontSize = '0.98rem';
                }
                return `<div class="micro-kpi-amt-local" style="font-size:${fontSize}; letter-spacing:${letterSpacing}; color:${color}; font-variant-numeric:tabular-nums;" title="${formatted} ${currency}">${formatted} <small style="font-size:0.68rem; opacity:0.85;">${currency}</small></div>`;
            }

            function formatScaledKpiForeign(usdNum, bg = 'rgba(56,189,248,0.14)', color = '#38bdf8', border = 'rgba(56,189,248,0.25)') {
                const formatted = fmt(usdNum);
                const len = formatted.length;
                let fontSize = '0.86rem';
                if (len >= 12) fontSize = '0.66rem';
                else if (len >= 10) fontSize = '0.72rem';
                else if (len >= 8) fontSize = '0.78rem';
                return `<div class="micro-kpi-amt-foreign" style="font-size:${fontSize}; background:${bg}; color:${color}; border:1px solid ${border}; font-variant-numeric:tabular-nums;" title="≈ $${formatted}">≈ $${formatted}</div>`;
            }

            // 1. Net Sales (Pure clean display with trend and dual currencies)
            const sVal = document.getElementById('micro-sales-val');
            if (sVal) {
                const usd = toUSD(salesToday);
                sVal.innerHTML = `
                    ${formatScaledKpiAmount(salesToday, 'SDG', '#ffffff')}
                    ${formatScaledKpiForeign(usd, 'rgba(56,189,248,0.14)', '#38bdf8', 'rgba(56,189,248,0.25)')}
                `;
            }
            const sCnt = document.getElementById('micro-sales-count');
            if (sCnt) sCnt.remove();

            // 2. Combined Liquid Cash (Vaults + Banks + Cheques) with High-Contrast Gold USD Badge
            let cashTotal = 0;
            M_VAULTS.forEach(v => { cashTotal += parseFloat(v.amount || 0); });
            const cVal = document.getElementById('micro-cash-val');
            if (cVal) {
                const usd = toUSD(cashTotal);
                cVal.innerHTML = `
                    ${formatScaledKpiAmount(cashTotal, 'SDG', '#34d399')}
                    ${formatScaledKpiForeign(usd, 'rgba(245,158,11,0.18)', '#fbbf24', 'rgba(245,158,11,0.35)')}
                `;
            }
            const vCnt = document.getElementById('micro-vaults-count');
            if (vCnt) vCnt.remove();

            // 3. Outstanding Receivables (Total Debt + Overdue)
            let debtTotal = 0;
            M_CUSTOMERS.forEach(c => {
                const b = parseFloat(c.balance || 0);
                if (b > 0) debtTotal += b;
            });
            const rVal = document.getElementById('micro-receivables-val');
            if (rVal) {
                const usd = toUSD(debtTotal);
                rVal.innerHTML = `
                    ${formatScaledKpiAmount(debtTotal, 'SDG', '#fb7185')}
                    ${formatScaledKpiForeign(usd, 'rgba(252,211,77,0.14)', '#fcd34d', 'rgba(252,211,77,0.25)')}
                `;
            }
            const oVal = document.getElementById('micro-overdue-val');
            if (oVal) oVal.innerText = debtTotal > 0 ? `${fmt(debtTotal * 0.35)} SDG متأخر` : 'سداد منتظم';

            // 4. Inventory Valuation Snapshot
            let stockVal = 0;
            let criticalCount = 0;
            M_ITEMS.forEach(it => {
                const q = parseFloat(it.stock || 0);
                const cost = parseFloat(it.cost || it.price || 0);
                stockVal += (q * cost);
                if (q <= (RuleAlertEngine?.rules?.safetyStockUnits || 15)) criticalCount++;
            });
            const iVal = document.getElementById('micro-inventory-val');
            if (iVal) {
                const usd = toUSD(stockVal);
                iVal.innerHTML = `
                    ${formatScaledKpiAmount(stockVal, 'SDG', '#fbbf24')}
                    ${formatScaledKpiForeign(usd, 'rgba(103,232,249,0.14)', '#67e8f9', 'rgba(103,232,249,0.25)')}
                `;
            }
            const iCnt = document.getElementById('micro-stock-items-count');
            if (iCnt) iCnt.innerText = `${M_ITEMS.length} صنف`;
            const critCnt = document.getElementById('micro-critical-stock-count');
            if (critCnt) critCnt.remove();
            const invGrand = document.getElementById('inventory-grand-total');
            if (invGrand) invGrand.innerHTML = `${fmt(stockVal)} <small style="font-size:0.8rem;">SDG</small> <span style="font-size:0.8rem; margin-inline-start:6px; color:var(--text-muted); font-weight:700;">(≈ $${fmt(toUSD(stockVal))})</span>`;
        }

        // ═════════════════════════════════════════════════════════════════
        // 🧠 SMART NOTIFICATION & BUSINESS RULE ENGINE
        // ═════════════════════════════════════════════════════════════════
        const RuleAlertEngine = {
            rules: {
                highTicketLimit: 5000000,
                minMarginPct: 5,
                creditLimit: 3000000,
                safetyStockUnits: 15
            },
            alerts: [],

            init() {
                this.loadSettings();
                this.scanAndRender();
            },

            loadSettings() {
                try {
                    const saved = JSON.parse(localStorage.getItem('magaiees_rule_settings') || '{}');
                    if (saved.highTicketLimit) this.rules.highTicketLimit = parseFloat(saved.highTicketLimit);
                    if (saved.minMarginPct) this.rules.minMarginPct = parseFloat(saved.minMarginPct);
                    if (saved.creditLimit) this.rules.creditLimit = parseFloat(saved.creditLimit);
                    if (saved.safetyStockUnits) this.rules.safetyStockUnits = parseFloat(saved.safetyStockUnits);
                } catch(e){}
            },

            saveSettings(newRules) {
                this.rules = { ...this.rules, ...newRules };
                localStorage.setItem('magaiees_rule_settings', JSON.stringify(this.rules));
                this.scanAndRender();
                if (window.showModernToast) {
                    window.showModernToast('✅ تم حفظ قواعد الأعمال وتحديث رادار المراقبة', 'success', 2200);
                }
            },

            scanAndRender() {
                const resolved = JSON.parse(localStorage.getItem('magaiees_resolved_alerts') || '{}');
                const list = [];

                // Alert Type C: "Credit Limit Exceeded"
                let cFound = 0;
                M_CUSTOMERS.forEach(c => {
                    const bal = parseFloat(c.balance || 0);
                    if (bal > this.rules.creditLimit && cFound < 2) {
                        const alertId = 'c_' + (c.id || c.name);
                        list.push({
                            id: alertId,
                            type: 'type-c',
                            typeLabel: '🔴 سقف الائتمان',
                            priority: 'عاجل جداً',
                            title: `تجاوز سقف الائتمان: ${c.name}`,
                            desc: `المديونية الحالية ${fmt(bal)} SDG وتجاوزت السقف (${fmt(this.rules.creditLimit)} SDG) بمقدار ${fmt(bal - this.rules.creditLimit)} SDG.`,
                            amount: bal,
                            resolved: !!resolved[alertId],
                            resolution: resolved[alertId] || null,
                            cta1: { label: 'موافقة على التجاوز', action: `RuleAlertEngine.approveOverdraft('${alertId}')`, cls: 'cta-approve' },
                            cta2: { label: 'إيقاف الطلب', action: `RuleAlertEngine.holdOrder('${alertId}')`, cls: 'cta-reject' }
                        });
                        cFound++;
                    }
                });
                // No sample fallback — only show real credit alerts

                // Alert Type B: "Below-Margin / Cost Violation"
                let bFound = 0;
                M_ITEMS.forEach(it => {
                    const price = parseFloat(it.price || 0);
                    const cost = parseFloat(it.cost || price * 0.9);
                    if (cost > 0 && price > 0) {
                        const marginPct = ((price - cost) / cost) * 100;
                        if (marginPct < this.rules.minMarginPct && bFound < 2) {
                            const alertId = 'b_' + it.id;
                            list.push({
                                id: alertId,
                                type: 'type-b',
                                typeLabel: '⚠️ هامش ربح دون التكلفة',
                                priority: 'تحذير مالي',
                                title: `هامش ربح حرج: ${it.name}`,
                                desc: `سعر البيع (${fmt(price)}) قريب من التكلفة (${fmt(cost)}) بهامش ${marginPct.toFixed(1)}% فقط وهو أقل من الحد الأدنى (${this.rules.minMarginPct}%).`,
                                amount: price,
                                resolved: !!resolved[alertId],
                                resolution: resolved[alertId] || null,
                                cta1: { label: 'تعديل السعر فوراً', action: `RuleAlertEngine.reviewMargin('${alertId}', '${it.id}')`, cls: 'cta-action' },
                                cta2: { label: 'تجاهل مؤقت', action: `RuleAlertEngine.dismissAlert('${alertId}')`, cls: 'cta-reject' }
                            });
                            bFound++;
                        }
                    }
                });
                // No sample fallback — only show real margin alerts

                // Alert Type A: "High-Ticket Sale"
                let aFound = 0;
                M_TRANSACTIONS.forEach(tx => {
                    const amt = parseFloat(tx.amount || tx.total || 0);
                    if (amt >= this.rules.highTicketLimit && aFound < 2) {
                        const alertId = 'a_' + (tx.id || tx.voucher_no || Math.random());
                        list.push({
                            id: alertId,
                            type: 'type-a',
                            typeLabel: '💎 فاتورة بيع كبرى',
                            priority: 'صفقة استثنائية',
                            title: `فاتورة بيع ضخمة: ${fmt(amt)} SDG`,
                            desc: `تم تسجيل فاتورة كبرى للسيد (${tx.to_account || tx.customer_name || 'عميل نقدي'}) تجاوزت حد الصفقات الكبرى (${fmt(this.rules.highTicketLimit)} SDG).`,
                            amount: amt,
                            resolved: !!resolved[alertId],
                            resolution: resolved[alertId] || null,
                            cta1: { label: 'إرسال إشعار واتساب', action: `RuleAlertEngine.shareHighTicket('${alertId}', ${amt})`, cls: 'cta-approve' },
                            cta2: { label: 'تدقيق السند', action: `RuleAlertEngine.dismissAlert('${alertId}')`, cls: 'cta-action' }
                        });
                        aFound++;
                    }
                });
                // No sample fallback — only show real big invoice alerts

                // Alert Type D: "Critical Stock Depletion"
                let dFound = 0;
                M_ITEMS.forEach(it => {
                    const stk = parseFloat(it.stock || 0);
                    if (stk <= this.rules.safetyStockUnits && dFound < 2) {
                        const alertId = 'd_' + it.id;
                        list.push({
                            id: alertId,
                            type: 'type-d',
                            typeLabel: '📦 نفاد مخزون حرج',
                            priority: 'نواقص مستودع',
                            title: `نفاد مخزون: ${it.name}`,
                            desc: `المتبقي في المستودع (${fmt(stk)} وحدة) وبلغ حد الأمان (${this.rules.safetyStockUnits} وحدة). مطلوب توريد عاجل.`,
                            amount: stk,
                            resolved: !!resolved[alertId],
                            resolution: resolved[alertId] || null,
                            cta1: { label: 'طلب شراء عاجل', action: `RuleAlertEngine.reorderStock('${alertId}', '${it.id}')`, cls: 'cta-action' },
                            cta2: { label: 'تحديث الجرد', action: `RuleAlertEngine.dismissAlert('${alertId}')`, cls: 'cta-reject' }
                        });
                        dFound++;
                    }
                });
                // No sample fallback — only show real stock alerts

                this.alerts = list;
                const activeAlerts = list.filter(a => !a.resolved);

                // Update counter badges
                const totalActiveCount = activeAlerts.length;
                ['header-alert-count', 'alert-total-count', 'bnav-approvals-badge', 'count-app-all'].forEach(id => {
                    const el = document.getElementById(id);
                    if (el) el.innerText = totalActiveCount;
                });
                const countC = activeAlerts.filter(a => a.type === 'type-c').length;
                const countB = activeAlerts.filter(a => a.type === 'type-b').length;
                const countA = activeAlerts.filter(a => a.type === 'type-a').length;
                const countD = activeAlerts.filter(a => a.type === 'type-d').length;
                if (document.getElementById('count-app-c')) document.getElementById('count-app-c').innerText = countC;
                if (document.getElementById('count-app-b')) document.getElementById('count-app-b').innerText = countB;
                if (document.getElementById('count-app-a')) document.getElementById('count-app-a').innerText = countA;
                if (document.getElementById('count-app-d')) document.getElementById('count-app-d').innerText = countD;

                this.renderSnapCarousel(activeAlerts);
                this.renderApprovalsHub(list);
            },

            renderSnapCarousel(activeAlerts) {
                const container = document.getElementById('alert-carousel-container');
                if (!container) return;
                if (activeAlerts.length === 0) {
                    container.innerHTML = `
                        <div style="padding:14px; text-align:center; width:100%; color:var(--emerald); font-weight:800; font-size:0.85rem;">
                            ✨ كافة المعاملات والمخزون وسقوف الائتمان متوافقة تماماً مع قواعد العمل!
                        </div>
                    `;
                    return;
                }
                let html = '';
                activeAlerts.forEach(a => {
                    html += `
                        <div class="alert-card-snap alert-${a.type}" id="carousel-alert-${a.id}">
                            <div class="alert-card-top">
                                <span class="alert-priority-tag">${a.typeLabel}</span>
                                <span style="font-size:0.78rem; color:var(--text-muted); font-weight:700;">${a.priority}</span>
                            </div>
                            <div class="alert-title-row">
                                <span>${a.title}</span>
                            </div>
                            <div class="alert-desc-text">${a.desc}</div>
                            <div class="alert-actions-row">
                                <button type="button" class="alert-cta-btn ${a.cta1.cls}" onclick="${a.cta1.action}">
                                    ${a.cta1.label}
                                </button>
                                <button type="button" class="alert-cta-btn ${a.cta2.cls}" onclick="${a.cta2.action}">
                                    ${a.cta2.label}
                                </button>
                            </div>
                        </div>
                    `;
                });
                container.innerHTML = html;
            },

            renderApprovalsHub(allAlerts) {
                const container = document.getElementById('approvals-cards-container');
                if (!container) return;
                let html = '';
                allAlerts.forEach(a => {
                    const isRes = a.resolved;
                    html += `
                        <div class="approval-card ${isRes ? 'resolved' : ''} alert-${a.type}" data-type="${a.type}" id="approval-card-${a.id}">
                            <div style="display:flex; justify-content:space-between; align-items:center;">
                                <span class="alert-priority-tag">${a.typeLabel}</span>
                                <span style="font-size:0.74rem; font-weight:800; color:${isRes ? 'var(--emerald)' : 'var(--amber)'};">
                                    ${isRes ? '✅ تم اتخاذ الإجراء: ' + a.resolution : '⚡ بانتظار اعتماد الإدارة'}
                                </span>
                            </div>
                            <div style="font-size:0.95rem; font-weight:900; color:var(--text-main);">${a.title}</div>
                            <div style="font-size:0.8rem; color:var(--text-muted); line-height:1.45;">${a.desc}</div>
                            ${!isRes ? `
                                <div style="display:flex; gap:8px; margin-top:4px;">
                                    <button type="button" class="alert-cta-btn ${a.cta1.cls}" style="padding:10px; font-size:0.82rem;" onclick="${a.cta1.action}">
                                        ${a.cta1.label}
                                    </button>
                                    <button type="button" class="alert-cta-btn ${a.cta2.cls}" style="padding:10px; font-size:0.82rem;" onclick="${a.cta2.action}">
                                        ${a.cta2.label}
                                    </button>
                                </div>
                            ` : `
                                <button type="button" class="alert-cta-btn" style="background:var(--surface-2); color:var(--text-muted); padding:6px;" onclick="RuleAlertEngine.reopenAlert('${a.id}')">
                                    إعادة فتح التنبيه 🔄
                                </button>
                            `}
                        </div>
                    `;
                });
                container.innerHTML = html;
            },

            approveOverdraft(alertId) {
                triggerHaptic('heavy');
                this.markResolved(alertId, 'موافقة استثنائية على التجاوز');
                if (window.showModernToast) {
                    window.showModernToast('✅ تمت الموافقة على تجاوز سقف الائتمان والسماح بالفوترة', 'success', 2500);
                }
            },

            holdOrder(alertId) {
                triggerHaptic('medium');
                this.markResolved(alertId, 'إيقاف الطلب وتجميد الحساب');
                if (window.showModernToast) {
                    window.showModernToast('🛑 تم إيقاف الطلب وتجميد البيع الآجل للحساب', 'warning', 2500);
                }
            },

            reorderStock(alertId, itemId) {
                triggerHaptic('medium');
                this.markResolved(alertId, 'أمر شراء وتوريد');
                openBottomSheet('sheet-purchase');
                if (itemId) {
                    setTimeout(() => {
                        const sel = document.getElementById('purchase-item');
                        if (sel) {
                            sel.value = itemId;
                            handlePurchaseItemSelect(sel);
                        }
                    }, 200);
                }
            },

            reviewMargin(alertId, itemId) {
                triggerHaptic('light');
                this.markResolved(alertId, 'مراجعة وتعديل السعر');
                if (window.showModernToast) {
                    window.showModernToast('📈 تم تحويل الصنف للتسعير الجديد لتفادي الخسارة', 'info', 2500);
                }
            },

            shareHighTicket(alertId, amount) {
                triggerHaptic('light');
                const text = `💎 تنبيه صفقة استثنائية - مقاييس ERP\nتم اعتماد فاتورة بيع كبرى بقيمة: ${fmt(amount)} SDG\nالتاريخ: ${new Date().toLocaleDateString('ar-EG')}`;
                window.open(`https://api.whatsapp.com/send?text=${encodeURIComponent(text)}`, '_blank');
                this.markResolved(alertId, 'مشاركة واعتماد الإشعار');
            },

            dismissAlert(alertId) {
                triggerHaptic('light');
                this.markResolved(alertId, 'تم التحقق والتجاهل');
            },

            reopenAlert(alertId) {
                triggerHaptic('light');
                const resolved = JSON.parse(localStorage.getItem('magaiees_resolved_alerts') || '{}');
                delete resolved[alertId];
                localStorage.setItem('magaiees_resolved_alerts', JSON.stringify(resolved));
                this.scanAndRender();
            },

            markResolved(alertId, reason) {
                const resolved = JSON.parse(localStorage.getItem('magaiees_resolved_alerts') || '{}');
                resolved[alertId] = reason;
                localStorage.setItem('magaiees_resolved_alerts', JSON.stringify(resolved));
                this.scanAndRender();
            }
        };

        // ═════════════════════════════════════════════════════════════════
        // 🧾 VIEW RENDERING FUNCTIONS (TRANSACTIONS, LEDGERS, INVENTORY)
        // ═════════════════════════════════════════════════════════════════
        let CURRENT_TX_FILTER = 'all';
        function filterTransactionsView(type, btn) {
            triggerHaptic('light');
            CURRENT_TX_FILTER = type;
            document.querySelectorAll('#view-transactions .cat-pill').forEach(p => p.classList.remove('active'));
            if (btn) btn.classList.add('active');
            renderTransactionsView();
        }

        function onTxSearchInput(query) {
            renderTransactionsView(query);
        }

        function renderTransactionsView(searchQuery = '') {
            const container = document.getElementById('tx-view-feed-container');
            if (!container) return;
            const q = (searchQuery || '').trim().toLowerCase();
            let filtered = M_TRANSACTIONS.filter(tx => {
                const t = (tx.type || tx.operation_type || '').toLowerCase();
                if (CURRENT_TX_FILTER === 'sale') return t.includes('sale') || t.includes('بيع');
                if (CURRENT_TX_FILTER === 'purchase') return t.includes('purchase') || t.includes('شراء');
                if (CURRENT_TX_FILTER === 'receipt') return t.includes('receipt') || t.includes('قبض');
                if (CURRENT_TX_FILTER === 'payment') return t.includes('payment') || t.includes('صرف') || t.includes('disburse');
                return true;
            });
            if (q) {
                filtered = filtered.filter(tx => {
                    const text = `${tx.id || ''} ${tx.voucher_no || ''} ${tx.from_account || ''} ${tx.to_account || ''} ${tx.notes || ''} ${tx.amount || ''}`.toLowerCase();
                    return text.includes(q);
                });
            }

            if (filtered.length === 0) {
                container.innerHTML = `
                    <div style="padding:30px 14px; text-align:center; color:var(--text-muted);">
                        <i class="fa-solid fa-receipt" style="font-size:2.5rem; opacity:0.3; margin-bottom:10px; display:block;"></i>
                        <p style="font-weight:700;">لا توجد حركات مسجلة تطابق التصفية الحالية</p>
                    </div>
                `;
                return;
            }

            let html = '';
            filtered.forEach(tx => {
                const amt = parseFloat(tx.amount || tx.total || 0);
                const isIncoming = tx.type === 'receipt' || tx.type === 'sale';
                html += `
                    <div class="activity-item" style="padding:12px; margin-bottom:10px; background:var(--surface-card); border:1.5px solid var(--border-glass); border-radius:14px; display:flex; flex-direction:column; gap:8px;">
                        <div style="display:flex; align-items:center; justify-content:space-between; gap:10px; width:100%;">
                            <div style="display:flex; align-items:center; gap:10px; min-width:0; flex:1;">
                                <div class="act-icon" style="background:${isIncoming ? 'rgba(16,185,129,0.15)' : 'rgba(244,63,94,0.15)'}; color:${isIncoming ? 'var(--emerald)' : 'var(--rose)'}; border:1px solid ${isIncoming ? 'var(--emerald)' : 'var(--rose)'}; width:38px; height:38px; border-radius:10px; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                                    <i class="fa-solid ${isIncoming ? 'fa-arrow-down-left' : 'fa-arrow-up-right-from-square'}"></i>
                                </div>
                                <div style="min-width:0; flex:1;">
                                    <div style="display:flex; align-items:center; gap:6px;">
                                        <span style="font-size:0.86rem; font-weight:900; color:var(--text-main); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                                            ${tx.to_account || tx.from_account || tx.customer_name || 'حركة مالية'}
                                        </span>
                                        <span style="font-size:0.78rem; padding:1px 6px; border-radius:6px; background:var(--surface-2); color:var(--text-muted); font-family:monospace;">
                                            #${tx.voucher_no || tx.id || '---'}
                                        </span>
                                    </div>
                                    <span style="font-size:0.73rem; color:var(--text-muted); display:block; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                                        ${tx.date || 'اليوم'} • ${tx.notes || (isIncoming ? 'سند قبض / بيع' : 'سند صرف / شراء')}
                                    </span>
                                </div>
                            </div>
                            <div style="text-align:left; flex-shrink:0;">
                                <div style="font-family:'Inter',sans-serif; font-size:1.05rem; font-weight:900; color:${isIncoming ? 'var(--emerald)' : 'var(--rose)'};">
                                    ${isIncoming ? '+' : '-'}${fmt(amt)} <small style="font-size:0.76rem;">SDG</small>
                                </div>
                            </div>
                        </div>

                        <!-- شريط الأزرار الموحد لكل حركة: [تعديل] [حذف] [طباعة] [واتساب] -->
                        <div class="tx-item-actions-row">
                            <button type="button" class="btn-tx-mini mini-edit" onclick='window.UniversalActionEngine.editItem("transactions", ${JSON.stringify(tx).replace(/'/g, "&apos;")})' title="تعديل السند">
                                <i class="fa-solid fa-pen-to-square"></i> تعديل
                            </button>
                            <button type="button" class="btn-tx-mini mini-delete" onclick='window.UniversalActionEngine.deleteItem("transactions", ${JSON.stringify(tx).replace(/'/g, "&apos;")})' title="حذف السند">
                                <i class="fa-solid fa-trash-can"></i> حذف
                            </button>
                            <button type="button" class="btn-tx-mini mini-print" onclick='window.UniversalActionEngine.printItem("transactions", ${JSON.stringify(tx).replace(/'/g, "&apos;")})' title="طباعة إيصال">
                                <i class="fa-solid fa-print"></i> طباعة 🖨️
                            </button>
                            <button type="button" class="btn-tx-mini mini-wa" onclick='shareSingleTxWhatsApp(${JSON.stringify(tx).replace(/'/g, "&apos;")})' title="مشاركة واتساب">
                                <i class="fa-brands fa-whatsapp"></i> إرسال
                            </button>
                            <button type="button" class="btn-tx-mini mini-settings" onclick='openTxAuditSettings(${JSON.stringify(tx).replace(/'/g, "&apos;")})' title="ضبط وتدقيق المعاملة" style="color:#fbbf24; border-color:rgba(251,191,36,0.3);">
                                <i class="fa-solid fa-sliders"></i> ضبط
                            </button>
                        </div>
                    </div>
                `;
            });
            container.innerHTML = html;
        }

