                            rawId: s.id || i + 1,
                            name: s.name || 'الخزينة الرئيسية',
                            category: 'safe',
                            categoryName: 'خزينة',
                            balance: parseFloat(s.currentBalance ?? s.balance ?? 0),
                            phone: '',
                            icon: 'fa-vault',
                            color: '#10b981'
                        });
                    });
                } else {
                    safeItems.push({
                        id: 'safe_main',
                        rawId: 'safe_main',
                        name: 'الخزينة الرئيسية (كاش)',
                        category: 'safe',
                        categoryName: 'خزينة',
                        balance: 0,
                        phone: '',
                        icon: 'fa-vault',
