                    });
                }
            }

            // Add cash vaults from M_VAULTS
            M_VAULTS.forEach((v, idx) => {
                const isSafe = v.name.includes('خزن') || v.name.includes('كاش') || v.name.includes('صندوق');
                if (isSafe) {
