            }));

            // 4. Suppliers (🏢 الموردين)
            const supplierItems = [];
            const rawSups = window.SERVER_DATA?.suppliers || loadTenantArray('erp_suppliers_v1');
            if (rawSups.length > 0) {
                rawSups.forEach((s, i) => {
                    supplierItems.push({
