                                <div style="font-size:0.75rem; color:var(--text-muted);">هاتف: ${c.phone || 'غير مسجل'}</div>
                            </div>
                            <div style="text-align:left;">
                                <div style="font-size:1.15rem; font-weight:900; color:var(--rose); font-family:'Inter', sans-serif;">${fmt(c.balance)} SDG</div>
                                <button type="button" onclick="event.stopPropagation(); activeStatementCustomer=M_CUSTOMERS.find(x=>x.id==='${c.id}'); sendWhatsAppClaim();" style="background:rgba(34,197,94,0.18); border:1px solid #22c55e; color:#22c55e; border-radius:6px; padding:3px 8px; font-size:0.74rem; font-weight:800; cursor:pointer;">
                                    <i class="fa-brands fa-whatsapp"></i> مطالبة
                                </button>
                            </div>
                        </div>
                    `;
                });
            }
            document.getElementById('mobile-debtors-container').innerHTML = debtorsHtml;

            // Real Low Stock Radar from DB
            let stockHtml = '';
            const lowStockItems = [...M_ITEMS].slice(0, 5);
            if (lowStockItems.length === 0) {
                stockHtml = '<div style="text-align:center; padding:20px; color:var(--text-muted); font-size:0.85rem;">لا توجد أصناف في المستودع.</div>';
            } else {
                lowStockItems.forEach(it => {
                    stockHtml += `
                        <div class="radar-row">
                            <div>
                                <div class="radar-name">📦 ${it.name}</div>
                                <div style="font-size:0.75rem; color:var(--amber); font-weight:700;">سعر البيع: ${fmt(it.price)} SDG</div>
                            </div>
                            <div style="font-size:1.15rem; font-weight:900; color:var(--amber); font-family:'Inter', sans-serif;">
                                المتبقي: ${it.stock || 0}
                            </div>
                        </div>
                    `;
                });
            }
            document.getElementById('mobile-low-stock-container').innerHTML = stockHtml;
        }

        // Background Live Sync with Database
        function triggerBackgroundSync() {
            const token = localStorage.getItem('authToken');
            if (!token) return;
            fetch('api_index.php/sync/pull', {
                headers: { 'Authorization': 'Bearer ' + token }
            })
            .then(r => r.json())
            .then(data => {
                if (data.success && data.data) {
                    const u = JSON.parse(localStorage.getItem('user') || '{}');
                    const prefix = (u.tenant_id && u.tenant_id !== 'default') ? 'tenant_' + u.tenant_id + '_' : '';
                    Object.keys(data.data).forEach(k => {
                        try {
                            const val = typeof data.data[k] === 'string' ? data.data[k] : JSON.stringify(data.data[k]);
                            if (prefix) localStorage.setItem(prefix + k, val);
                            localStorage.setItem(k, val);
                        } catch(e){}
                    });
                }
            })
            .catch(() => {});
        }

        function pushChangesToBackend() {
            const token = localStorage.getItem('authToken');
            if (!token) return;
            const payload = {
                customers: loadTenantArray('erp_customers_v1'),
                suppliers: loadTenantArray('erp_suppliers_v1'),
                single_receipts: loadTenantArray('erp_single_receipts_v1'),
                single_payments: loadTenantArray('erp_single_payments_v1'),
                sales_invoices: loadTenantArray('erp_sales_invoices_v1'),
                purchase_invoices: loadTenantArray('erp_purchase_invoices_v1'),
                items: loadTenantArray('erp_items_v1')
            };
            fetch('api_index.php/sync/push', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token },
                body: JSON.stringify(payload)
            }).catch(() => {});
        }

        // ═════════════════════════════════════════════════════════════════
        // 🔢 MODULE: DUAL-NUMBERING ENGINE (OFFLINE VS. CLOUD OFFICIAL)
        // ═════════════════════════════════════════════════════════════════
        window.DualNumberingEngine = {
            prefixes: {
                sale: 'INV-OFF-',
                purchase: 'PUR-OFF-',
                receipt: 'IN-OFF-',
                disbursement: 'OUT-OFF-',
                audit: 'AUD-OFF-',
                transfer: 'TR-OFF-'
            },

            getStorageKey(type) {
                const getTenantKey = window.getTenantKey || ((k) => k);
                return getTenantKey('erp_dual_seq_' + type);
            },

            nextSequence(type) {
                const key = this.getStorageKey(type);
                let current = parseInt(localStorage.getItem(key) || '0', 10);
                current += 1;
                localStorage.setItem(key, String(current));
                const prefix = this.prefixes[type] || 'DOC-OFF-';
                return prefix + current;
            },

            peekCurrentSequence(type) {
                const key = this.getStorageKey(type);
                const current = parseInt(localStorage.getItem(key) || '0', 10);
                const prefix = this.prefixes[type] || 'DOC-OFF-';
                return prefix + (current + 1);
            },

            peekNextSequence(type) {
                return this.peekCurrentSequence(type);
            },

            createRecord(type, baseData = {}) {
                const localSeq = this.nextSequence(type);
                return {
                    ...baseData,
                    local_seq: localSeq,
                    sync_status: 'PENDING_OFFLINE',
                    official_server_id: null,
                    offline_created_at: new Date().toISOString()
                };
            },

            markSynced(localSeq, officialServerId, queueId = null) {
                if (!officialServerId) return;
                const stores = [
                    'erp_sales_invoices_v1',
                    'erp_purchase_invoices_v1',
                    'erp_financial_txs_v1',
                    'erp_single_receipts_v1',
                    'erp_single_payments_v1',
                    'erp_inventory_audits_v1',
                    'erp_transfers_v1'
                ];
                stores.forEach(stKey => {
                    const arr = loadTenantArray(stKey);
                    let changed = false;
                    arr.forEach(rec => {
                        const isMatch = (
                            (localSeq && (rec.local_seq === localSeq || rec.invoiceNo === localSeq || rec.voucherNo === localSeq || rec.waybillNo === localSeq || rec.id === localSeq)) ||
                            (queueId && (rec.id === queueId || rec.queue_id === queueId)) ||
                            (rec.official_server_id === officialServerId)
                        );
                        if (isMatch) {
                            rec.sync_status = 'SYNCED';
                            rec.official_server_id = officialServerId;
                            rec.server_ref = officialServerId;
                            rec.synced_at = new Date().toISOString();
                            if (!rec.offline_no) {
                                rec.offline_no = localSeq;
                            }
                            if (rec.voucherNo) {
                                rec.voucherNo = officialServerId;
                            }
                            if (rec.invoiceNo) {
                                rec.invoiceNo = officialServerId;
                            }
                            if (rec.id && (String(rec.id).includes('OFF') || String(rec.id).startsWith('REC-') || String(rec.id).startsWith('TX-'))) {
                                rec.id = officialServerId;
                            }
                            changed = true;
                        }
                    });
                    if (changed) {
                        saveTenantArray(stKey, arr);
                    }
                });

                // Update SERVER_DATA in-memory caches
                if (window.SERVER_DATA) {
                    if (officialServerId.startsWith('R')) {
                        window.SERVER_DATA.receipts = window.SERVER_DATA.receipts || [];
                        const exists = window.SERVER_DATA.receipts.some(r => r.id === officialServerId || r.voucherNo === officialServerId);
                        if (!exists) {
                            const recArr = loadTenantArray('erp_single_receipts_v1');
                            const match = recArr.find(r => r.id === officialServerId || r.voucherNo === officialServerId);
                            if (match) window.SERVER_DATA.receipts.unshift(match);
                        }
                    } else if (officialServerId.startsWith('E')) {
                        window.SERVER_DATA.payments = window.SERVER_DATA.payments || [];
                        const exists = window.SERVER_DATA.payments.some(p => p.id === officialServerId || p.voucherNo === officialServerId);
                        if (!exists) {
                            const payArr = loadTenantArray('erp_single_payments_v1');
                            const match = payArr.find(p => p.id === officialServerId || p.voucherNo === officialServerId);
                            if (match) window.SERVER_DATA.payments.unshift(match);
                        }
                    } else if (officialServerId.startsWith('INV-')) {
                        window.SERVER_DATA.sales = window.SERVER_DATA.sales || [];
                        const exists = window.SERVER_DATA.sales.some(s => s.id === officialServerId || s.invoiceNo === officialServerId);
                        if (!exists) {
                            const saleArr = loadTenantArray('erp_sales_invoices_v1');
                            const match = saleArr.find(s => s.id === officialServerId || s.invoiceNo === officialServerId);
                            if (match) window.SERVER_DATA.sales.unshift(match);
                        }
                    }
                }

                // Update VoucherNavigator live list and active view
                if (window.VoucherNavigator && Array.isArray(window.VoucherNavigator.vouchers)) {
                    let navUpdated = false;
                    window.VoucherNavigator.vouchers.forEach(v => {
                        if (v.voucherNo === localSeq || v.id === localSeq || v.local_seq === localSeq || (queueId && v.id === queueId)) {
                            v.voucherNo = officialServerId;
                            v.id = officialServerId;
                            v.official_server_id = officialServerId;
                            v.sync_status = 'SYNCED';
                            navUpdated = true;
                        }
                    });
                    if (window.VoucherNavigator.currentIndex >= 0 && navUpdated) {
                        window.VoucherNavigator.displayVoucher(window.VoucherNavigator.currentIndex);
                    } else if (window.VoucherNavigator.currentIndex === -1) {
                        const vObj = computeNextVoucherNo();
                        const vNoEl = document.getElementById('tx-voucher-no');
                        const vDispEl = document.getElementById('tx-voucher-display');
                        if (vNoEl) vNoEl.value = vObj.voucherNo;
                        if (vDispEl) vDispEl.textContent = vObj.voucherNo;
                    }
                }

                if (window.MobilePOS && window.MobilePOS.state.lastSubmittedInvoice) {
                    const last = window.MobilePOS.state.lastSubmittedInvoice;
                    if (last.local_seq === localSeq || last.invoiceNo === localSeq || last.id === localSeq || (queueId && last.id === queueId)) {
                        last.sync_status = 'SYNCED';
                        last.official_server_id = officialServerId;
                        last.server_ref = officialServerId;
                        last.invoiceNo = officialServerId;
                        const printSheet = document.getElementById('sheet-receipt-print');
                        if (printSheet && printSheet.classList.contains('active')) {
                            window.MobilePOS.openThermalReceiptSheet(last);
                        }
                    }
                }
                const liveBadge = document.getElementById('receipt-sync-badge');
                if (liveBadge && officialServerId) {
                    liveBadge.style.background = '#059669';
                    liveBadge.innerHTML = `✅ معتمد سحابياً: ${officialServerId}`;
                }
            }
        };

        // ═════════════════════════════════════════════════════════════════
        // 🛰️ OFFLINE-FIRST OUTBOX SYNCHRONIZATION ENGINE
        // ═════════════════════════════════════════════════════════════════
        window.OfflineOutboxEngine = {
            queue: [],
            isSimulatedOffline: false,
            realOnline: (typeof navigator !== 'undefined' ? navigator.onLine : true),
            isSyncing: false,
            lastHeartbeatMs: null,
            heartbeatInterval: null,
            autoSyncInterval: null,
            failedPings: 0,
            isCheckingHeartbeat: false,
            lastSyncAttempt: 0,
            lastSyncFailed: false,

            init() {
                try {
                    const saved = localStorage.getItem('erp_outbox_queue_v1');
                    this.queue = saved ? JSON.parse(saved) : [];
                    // Sanitize stuck items: if an item was left as SYNCING across app reload, reset to PENDING
                    this.queue.forEach(item => {
                        if (item.status === 'SYNCING') item.status = 'PENDING';
                    });
                } catch(e) {
                    this.queue = [];
                }

                // Prevent test simulation flags from sticking across app visits
                try { sessionStorage.removeItem('erp_sim_offline'); } catch(e) {}
                this.isSimulatedOffline = false;
                this.realOnline = (typeof navigator !== 'undefined' ? navigator.onLine : true);

                window.addEventListener('online', () => {
                    this.failedPings = 0;
                    this.lastSyncFailed = false;
                    this.lastSyncAttempt = 0;
                    this.setConnectionState(true);
                    this.checkHeartbeat(false);
                    this.flushQueueNow(false);
                });
                window.addEventListener('offline', () => {
                    this.failedPings = 3;
                    this.setConnectionState(false);
                });
                if (navigator.connection) {
                    try {
                        navigator.connection.addEventListener('change', () => {
                            if (navigator.onLine) {
                                this.lastSyncFailed = false;
                                this.lastSyncAttempt = 0;
                                this.checkHeartbeat(false);
                            }
                        });
                    } catch(e) {}
                }
                document.addEventListener('visibilitychange', () => {
                    if (!document.hidden && navigator.onLine) {
                        this.lastSyncFailed = false;
                        this.lastSyncAttempt = 0;
                        this.checkHeartbeat(false);
                    }
                });
                window.addEventListener('focus', () => {
                    if (navigator.onLine) {
                        this.lastSyncFailed = false;
                        this.lastSyncAttempt = 0;
                        this.checkHeartbeat(false);
                    }
                });

                // Adaptive heartbeat probe: every 10s when online, every 3s when offline
                this.startHeartbeatTimer();

                // Auto-sync watcher with smart backoff cooldown (never locks or endlessly spins)
                if (this.autoSyncInterval) clearInterval(this.autoSyncInterval);
                this.autoSyncInterval = setInterval(() => {
                    if (this.isOnline() && !this.isSyncing) {
                        const cooldown = this.lastSyncFailed ? 20000 : 5000;
                        if (Date.now() - (this.lastSyncAttempt || 0) < cooldown) return;

                        const hasPending = this.queue.some(q => ['PENDING', 'FAILED'].includes(String(q.status).toUpperCase()));
                        if (hasPending) {
                            this.flushQueueNow(false);
                        }
                    }
                }, 3000);

                // Initial UI render immediately based on navigator.onLine
                this.renderUI();
                // Non-blocking initial probe after page resources start settling
                setTimeout(() => this.checkHeartbeat(false), 500);
            },

            startHeartbeatTimer() {
                if (this.heartbeatInterval) clearInterval(this.heartbeatInterval);
                const intervalMs = this.realOnline ? 10000 : 3000;
                this.heartbeatInterval = setInterval(() => {
                    this.checkHeartbeat(false);
                }, intervalMs);
            },

            isOnline() {
                if (this.isSimulatedOffline) return false;
                if (typeof navigator !== 'undefined' && !navigator.onLine) return false;
                return Boolean(this.realOnline);
            },

            setConnectionState(isOnline, latency = null) {
                const wasOnline = this.realOnline;
                this.realOnline = Boolean(isOnline);
                if (latency !== null) this.lastHeartbeatMs = latency;

                if (wasOnline !== this.realOnline) {
                    this.startHeartbeatTimer(); // Adjust interval dynamically
                    this.renderUI();
                    if (this.realOnline) {
                        this.lastSyncFailed = false;
                        this.lastSyncAttempt = 0;
                        triggerHaptic('medium');
                        if (typeof playSoundEffect === 'function') playSoundEffect('success');
                        if (window.showModernToast) {
                            window.showModernToast('🟢 تم استعادة اتصال الإنترنت (النور أخضر) — جاري ترحيل ورفع كافة العمليات فوراً ⚡', 'success', 3000);
                        }
                        // Instantly drain all pending items upon internet recovery
                        this.flushQueueNow(false);
                    } else {
                        triggerHaptic('heavy');
                        if (typeof playSoundEffect === 'function') playSoundEffect('warning');
                        if (window.showModernToast) {
                            window.showModernToast('🔴 انقطع اتصال الإنترنت (النور أحمر) — البرنامج يعمل في وضع الأوفلاين والسندات تُحفظ محلياً', 'warning', 3500);
                        }
                    }
                } else {
                    this.renderUI();
                }
            },

            getBreakdown() {
                const pending = this.queue.filter(q => ['PENDING', 'FAILED', 'SYNCING'].includes(String(q.status).toUpperCase()));
                let vouchers = 0;
                let sales = 0;
                let others = 0;

                pending.forEach(it => {
                    const t = String(it.type || it.entity_name || '').toLowerCase();
                    if (t.includes('voucher') || t.includes('payment') || t.includes('receipt') || t.includes('cash') || t.includes('transfer')) {
                        vouchers++;
                    } else if (t.includes('sale') || t.includes('pos')) {
                        sales++;
                    } else {
                        others++;
                    }
                });

                return {
                    total: pending.length,
                    vouchers,
                    sales,
                    others
                };
            },

            handleNetworkChange() {
                this.checkHeartbeat(false);
            },

            toggleOfflineSimulation() {
                triggerHaptic('heavy');
                this.isSimulatedOffline = !this.isSimulatedOffline;
                sessionStorage.setItem('erp_sim_offline', this.isSimulatedOffline ? '1' : '0');
                this.setConnectionState(!this.isSimulatedOffline);

                if (this.isSimulatedOffline) {
                    if (window.showModernToast) {
                        window.showModernToast('📴 تم تفعيل محاكاة انقطاع الشبكة (النور أحمر)', 'warning', 2500);
                    }
                } else {
                    if (window.showModernToast) {
                        window.showModernToast('🌐 تم إلغاء المحاكاة واستعادة الاتصال (النور أخضر) — جاري التفريغ...', 'success', 2500);
                    }
                    this.flushQueueNow(false);
                }
            },

            async checkHeartbeat(isUserTriggered = false) {
                if (this.isCheckingHeartbeat) return;
                this.isCheckingHeartbeat = true;

                if (this.isSimulatedOffline) {
                    this.setConnectionState(false);
                    this.isCheckingHeartbeat = false;
                    return;
                }
                if (typeof navigator !== 'undefined' && !navigator.onLine) {
                    this.failedPings = 3;
                    this.setConnectionState(false);
                    this.isCheckingHeartbeat = false;
                    return;
                }

                if (isUserTriggered && window.showModernToast) {
                    window.showModernToast('⚡ جاري فحص الاتصال بالخادم وتحديث الحالة...', 'info', 1500);
                }

                // Generous timeout for challenging mobile / 3G / 4G cellular links
                const probeOnce = async (url, timeoutMs = 7500) => {
                    const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
                    const timeoutId = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;
                    const startTime = performance.now();
                    try {
                        const resp = await fetch(url, {
                            method: 'GET',
                            cache: 'no-store',
                            headers: { 'Cache-Control': 'no-cache', 'Pragma': 'no-cache' },
                            signal: controller ? controller.signal : undefined
                        });
                        if (timeoutId) clearTimeout(timeoutId);
                        if (resp.ok) {
                            return Math.round(performance.now() - startTime);
                        }
                    } catch(e) {
                        if (timeoutId) clearTimeout(timeoutId);
                    }
                    return null;
                };

                try {
                    // 1. Primary probe: dedicated 1-byte ping endpoint
                    let latency = await probeOnce('api/ping.php?t=' + Date.now(), 7500);

                    // 2. Secondary failover: heartbeat ping query on dashboard itself
                    if (latency === null) {
                        latency = await probeOnce('mobile-dashboard.php?action=heartbeat_ping&t=' + Date.now(), 6000);
                    }

                    if (latency !== null) {
                        // Confirmed connected to live cloud!
                        this.failedPings = 0;
                        this.setConnectionState(true, latency);

                        if (isUserTriggered && window.showModernToast) {
                            window.showModernToast(`🟢 الاتصال بالخادم ممتاز (النور أخضر) • زمن الاستجابة: ${latency}ms`, 'success', 2500);
                        }

                        // Auto-drain if pending transactions exist
                        const hasPending = this.queue.some(q => ['PENDING', 'FAILED', 'SYNCING'].includes(String(q.status).toUpperCase()));
                        if (hasPending && !this.isSyncing) {
                            this.flushQueueNow(false);
                        }
                    } else {
                        // Probe failed
                        this.failedPings++;
                        // Only switch to RED if navigator is offline OR 2 consecutive probes fail!
                        if (!navigator.onLine || this.failedPings >= 2) {
                            this.setConnectionState(false);
                            if (isUserTriggered && window.showModernToast) {
                                window.showModernToast('🔴 تعذر الوصول إلى الخادم — يرجى التأكد من توفر شبكة الإنترنت', 'warning', 3000);
                            }
                        }
                    }
                } finally {
                    this.isCheckingHeartbeat = false;
                }
            },


            generateUUID() {
                if (typeof crypto !== 'undefined' && crypto.randomUUID) {
                    return crypto.randomUUID();
                }
                return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
                    const r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
                    return v.toString(16);
                });
            },

            generateIdempotencyKey(type) {
                return this.generateUUID();
            },

            enqueue(type, payload, priority = 'NORMAL', title = null, summary = null, operation = 'INSERT') {
                triggerHaptic('light');
                const uuid = this.generateUUID();
                
                // Formulate human-readable description
                let itemTitle = title;
                let itemSummary = summary;
                let entityName = 'invoices';
                let recordId = payload?.invoiceNo || payload?.voucherNo || payload?.transferNo || payload?.auditNo || payload?.id || ('REC-' + Date.now());

                if (type === 'sale_invoice') {
                    entityName = 'sales_invoices';
                    itemTitle = itemTitle || `فاتورة بيع #${recordId}`;
                    itemSummary = itemSummary || `العميل: ${payload.customerName || 'عميل'} • ${typeof fmt === 'function' ? fmt(payload.total || payload.grandTotal || 0) : payload.total} SDG`;
                } else if (type === 'purchase_invoice') {
                    entityName = 'purchase_invoices';
                    itemTitle = itemTitle || `فاتورة توريد #${recordId}`;
                    itemSummary = itemSummary || `المورد: ${payload.supplierName || 'مورد'} • ${typeof fmt === 'function' ? fmt(payload.total || 0) : payload.total} SDG`;
                } else if (type.includes('receipt') || (payload && payload.type === 'receipt')) {
                    entityName = 'single_receipts';
                    itemTitle = itemTitle || `سند قبض #${recordId}`;
                    itemSummary = itemSummary || `المستلم منه: ${payload.beneficiaryName || payload.customerName || payload.toStatement || 'سند قبض'} • ${typeof fmt === 'function' ? fmt(payload.amountLocal || payload.amount || 0) : payload.amount} SDG`;
                } else if (type.includes('voucher') || type.includes('payment') || type.includes('disburse')) {
                    entityName = 'single_payments';
                    itemTitle = itemTitle || `سند صرف #${recordId}`;
                    itemSummary = itemSummary || `المستفيد: ${payload.beneficiaryName || payload.recipient || payload.toStatement || 'سند صرف'} • ${typeof fmt === 'function' ? fmt(payload.amountLocal || payload.amount || 0) : payload.amount} SDG`;
                } else if (type.includes('transfer')) {
                    entityName = 'stock_transfers';
                    itemTitle = itemTitle || `تحويل مخزني #${recordId}`;
                    itemSummary = itemSummary || `من المستودع الرئيسي إلى الفرع • ${payload.totalQty || (payload.items ? payload.items.length : 1)} وحدة`;
                } else if (type.includes('audit')) {
                    entityName = 'stock_transfers';
                    itemTitle = itemTitle || `جرد مخزني #${recordId}`;
                    itemSummary = itemSummary || `صنف: ${payload.itemName || 'صنف'} • فارق: ${payload.variance > 0 ? '+' : ''}${payload.variance || 0}`;
                } else if (type.includes('approval')) {
                    entityName = 'vouchers';
                    itemTitle = itemTitle || `قرار اعتماد #${recordId}`;
                    itemSummary = itemSummary || `القرار: ${payload.status === 'approved' ? 'موافقة' : 'رفض'} • ${payload.note || 'معتمد'}`;
                } else {
                    entityName = 'invoices';
                    itemTitle = itemTitle || `معاملة مالية ${type}`;
                    itemSummary = itemSummary || 'حفظ فوري محلياً في sync_queue';
                }

                const outboxRecord = {
                    id: uuid,                          // UUID (matches sync_queue.id)
                    entity_name: entityName,           // 'invoices', 'vouchers', 'stock_transfers'
                    record_id: String(recordId),       // matches sync_queue.record_id
                    operation: operation,              // 'INSERT', 'UPDATE'
                    payload: typeof payload === 'string' ? payload : JSON.stringify(payload), // JSON
                    status: 'PENDING',                 // 'PENDING', 'SYNCING', 'FAILED', 'SYNCED'
                    retry_count: 0,
                    created_at: new Date().toISOString(),

                    // Ergonomic UI view helpers
                    type: type,
                    priority: priority,
                    title: itemTitle,
                    summary: itemSummary,
                    synced_at: null,
                    lastError: null,
                    serverRef: null
                };

                this.queue.unshift(outboxRecord);
                this.saveQueue();
                this.renderUI();

                // Ultra-responsive proactive flush: trigger immediately within 50ms if online!
                if (this.isOnline()) {
                    setTimeout(() => this.flushQueueNow(false), 50);
                }

                return outboxRecord;
            },

            saveQueue() {
                try {
                    localStorage.setItem('erp_outbox_queue_v1', JSON.stringify(this.queue));
                } catch(e){}
            },

            async flushQueueNow(isManual = false) {
                if (!this.isOnline()) {
                    if (isManual && window.showModernToast) {
                        window.showModernToast('⚠️ الجهاز غير متصل حالياً (النور أحمر)! السندات محفوظة محلياً وسيتم ترحيلها فور توفر الإنترنت.', 'warning', 3000);
                    }
                    this.renderUI();
                    return;
                }

                if (this.isSyncing) return;

                const pendingItems = this.queue.filter(q => ['PENDING', 'FAILED', 'SYNCING'].includes(String(q.status).toUpperCase()));
                if (pendingItems.length === 0) {
                    if (isManual && window.showModernToast) {
                        window.showModernToast('✅ جدول المزامنة متطابق بالكامل مع السيرفر! لا توجد حركات معلقة.', 'success', 2500);
                    }
                    this.renderUI();
                    return;
                }

                this.isSyncing = true;
                triggerHaptic('light');

                // Mark items as SYNCING
                pendingItems.forEach(it => it.status = 'SYNCING');
                this.saveQueue();
                this.renderUI();

                const btnFlush = document.getElementById('btn-flush-outbox');
                if (btnFlush) {
                    btnFlush.disabled = true;
                    btnFlush.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> جاري ترحيل ورفع العمليات إلى السيرفر...';
                }

                try {
                    const pushBatch = {
                        tenant_id: window.SERVER_DATA?.tenantId || 1,
                        items: pendingItems.map(it => ({
                            id: it.id,
                            entity_name: it.entity_name || 'invoices',
                            record_id: it.record_id,
                            operation: it.operation || 'INSERT',
                            payload: it.payload,
                            status: 'PENDING',
                            retry_count: it.retry_count || 0,
                            created_at: it.created_at
                        }))
                    };

                    let serverResponse = null;
                    let syncSuccess = false;

                    // 1. Try Batch push with 6s timeout
                    try {
                        const controller = typeof AbortController !== 'undefined' ? new AbortController() : null;
                        const tId = controller ? setTimeout(() => controller.abort(), 6000) : null;
                        const response = await fetch('api/sync_queue_api.php?action=push', {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify(pushBatch),
                            signal: controller ? controller.signal : undefined
                        });
                        if (tId) clearTimeout(tId);
                        if (response.ok) {
                            serverResponse = await response.json();
                            if (serverResponse && serverResponse.success !== false) {
                                syncSuccess = true;
                            }
                        }
                    } catch(netErr) {
                        console.warn('⚠️ Batch sync failed, trying weak-network sequential upload...', netErr);
                    }

                    // 2. Weak Connection Adaptive Mode ("نت ضعيف جداً"): Upload one-by-one
                    if (!syncSuccess) {
                        let singleSuccessCount = 0;
                        for (const it of pendingItems) {
                            try {
                                const singleBatch = {
                                    tenant_id: window.SERVER_DATA?.tenantId || 1,
                                    items: [{
                                        id: it.id,
                                        entity_name: it.entity_name || 'invoices',
                                        record_id: it.record_id,
                                        operation: it.operation || 'INSERT',
                                        payload: it.payload,
                                        status: 'PENDING',
                                        retry_count: it.retry_count || 0,
                                        created_at: it.created_at
                                    }]
                                };
                                const sCtrl = typeof AbortController !== 'undefined' ? new AbortController() : null;
                                const sTid = sCtrl ? setTimeout(() => sCtrl.abort(), 6000) : null;
                                const sResp = await fetch('api/sync_queue_api.php?action=push', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify(singleBatch),
                                    signal: sCtrl ? sCtrl.signal : undefined
                                });
                                if (sTid) clearTimeout(sTid);
                                if (sResp.ok) {
                                    const sJson = await sResp.json();
                                    if (sJson && sJson.success !== false && sJson.results && sJson.results.length > 0) {
                                        const rItem = sJson.results[0];
                                        const officialId = rItem.server_id || rItem.official_server_id;
                                        it.status = 'SYNCED';
                                        it.sync_status = 'SYNCED';
                                        it.synced_at = new Date().toISOString();
                                        it.server_id = officialId;
                                        it.official_server_id = officialId;
                                        it.serverRef = rItem.server_ref || officialId;
                                        it.lastError = null;

                                        if (window.DualNumberingEngine) {
                                            window.DualNumberingEngine.markSynced(it.record_id || it.local_seq, officialId, it.id);
                                        }
                                        singleSuccessCount++;
                                        this.saveQueue();
                                        this.renderUI(); // Live decrement of red counter badge
                                    }
                                }
                            } catch(sErr) {
                                it.status = 'PENDING';
                                it.retry_count = (it.retry_count || 0) + 1;
                                break; // Network died again, keep rest in queue
                            }
                        }
                        if (singleSuccessCount > 0) {
                            syncSuccess = true;
                        }
                    } else if (serverResponse && serverResponse.results) {
                        // Batch confirmed
                        pendingItems.forEach((it, idx) => {
                            it.status = 'SYNCED';
                            it.sync_status = 'SYNCED';
                            it.synced_at = new Date().toISOString();
                            const sRef = serverResponse.results.find(r => r.id === it.id || r.queue_id === it.id || r.record_id === it.record_id);
                            const officialId = sRef?.server_id || sRef?.official_server_id || ('#' + (10500 + idx));
                            it.server_id = officialId;
                            it.official_server_id = officialId;
                            it.serverRef = sRef?.server_ref || officialId;
                            it.lastError = null;

                            // Dual Numbering sync update
                            if (window.DualNumberingEngine) {
                                window.DualNumberingEngine.markSynced(it.record_id || it.local_seq, officialId, it.id);
                            }
                        });
                    }

                    if (syncSuccess) {
                        // 🔄 Refresh all live data on screen immediately
                        if (typeof refreshMobileData === 'function') refreshMobileData();
                        if (window.VoucherNavigator && typeof window.VoucherNavigator.loadVouchers === 'function') {
                            window.VoucherNavigator.loadVouchers();
                        }

                        if (typeof playSoundEffect === 'function') playSoundEffect('success');
                        triggerHaptic('heavy');

                        const syncedCount = pendingItems.filter(it => it.status === 'SYNCED').length;
                        this.lastSyncFailed = false;
                        this.lastSyncAttempt = Date.now();
                        const serials = pendingItems
                            .filter(it => it.status === 'SYNCED' && it.official_server_id)
                            .map(it => it.official_server_id);
                        const serialListStr = serials.slice(0, 3).join(', ') + (serials.length > 3 ? ` و+${serials.length - 3} أخرى` : '');
                        const msg = serials.length > 0 
                            ? `🟢 تم الاتصال بالإنترنت! تم تدوين (${syncedCount}) عملية في الموقع الحي بأرقام تسلسلية رسمية: [${serialListStr}] ⚡`
                            : `🟢 تم الاتصال بالإنترنت! تم تدوين وتوثيق (${syncedCount}) عملية في الموقع الحي بنجاح ⚡`;
                        if (window.showModernToast) {
                            window.showModernToast(msg, 'success', 5000);
                        }

                        // Auto-clean confirmed items after 4 seconds
                        setTimeout(() => {
                            this.clearSyncedItems(false);
                        }, 4000);

                    } else {
                        // 🔴 Network failed — keep items PENDING for retry with cooldown
                        this.lastSyncFailed = true;
                        this.lastSyncAttempt = Date.now();
                        pendingItems.forEach(it => {
                            it.status = 'PENDING';
                            it.retry_count = (it.retry_count || 0) + 1;
                            it.lastError = 'Network sync failed at ' + new Date().toISOString();
                        });
                        if (isManual && window.showModernToast) {
                            window.showModernToast('⚠️ تعذر إتمام المزامنة — الحركات محفوظة في الطابور وسيعاد المحاولة تلقائياً', 'warning', 3500);
                        }
                    }

                    this.saveQueue();
                } catch(err) {
                    this.lastSyncFailed = true;
                    this.lastSyncAttempt = Date.now();
                    pendingItems.forEach(it => {
                        it.status = 'PENDING';
                        it.retry_count = (it.retry_count || 0) + 1;
                        it.lastError = err.message || 'خطأ في الاتصال';
                    });
                    this.saveQueue();
                    if (isManual && window.showModernToast) {
                        window.showModernToast('❌ تعذر إتمام المزامنة • تم الإبقاء على الحركات في الطابور', 'danger', 3000);
                    }
                } finally {
                    this.isSyncing = false;
                    if (btnFlush) {
                        btnFlush.disabled = false;
                        btnFlush.innerHTML = '<i class="fa-solid fa-cloud-arrow-up"></i> تفريغ ومزامنة فورية الآن ⚡';
                    }
                    this.renderUI();
                }
            },

            clearSyncedItems(showToast = true) {
                const beforeCount = this.queue.length;
                this.queue = this.queue.filter(q => String(q.status).toUpperCase() !== 'SYNCED');
                this.saveQueue();
                this.renderUI();
                const removed = beforeCount - this.queue.length;
                if (showToast && removed > 0 && window.showModernToast) {
                    window.showModernToast(`🧹 تم تنظيف (${removed}) حركات مؤكدة من السجل المحلي`, 'info', 2000);
                }
            },

            seedDemoTransactions() {
                triggerHaptic('light');
                const sampleInvoices = [
                    {
                        id: 'e4b2d380-60b1-4f22-bc51-0a6381a1796d',
                        entity_name: 'invoices',
                        record_id: 'INV-882194',
                        operation: 'INSERT',
                        type: 'sale_invoice',
                        priority: 'HIGH',
                        title: 'فاتورة بيع نقدي #INV-882194',
                        summary: 'شركة الفهد للمقاولات • 4,850,000 SDG',
                        payload: { invoiceNo: 'INV-882194', customerName: 'شركة الفهد للمقاولات', total: 4850000, items: [{ name: 'حديد تسليح 12 ملم', qty: 5, price: 850000 }] }
                    },
                    {
                        id: 'b7c1d2e3-5f6a-4b2c-9d3e-4f5a6b7c8d9e',
                        entity_name: 'stock_transfers',
                        record_id: 'TR-2026-0042',
                        operation: 'INSERT',
                        type: 'stock_transfer',
                        priority: 'NORMAL',
                        title: 'تحويل مخزني #TR-2026-0042',
                        summary: 'مستودع السجانة المركزي ➔ فرع الكلاكلة • 5 طن حديد تسليح',
                        payload: { transferNo: 'TR-2026-0042', sourceWh: 'central', destWh: 'kalakla', totalQty: 5 }
                    },
                    {
                        id: 'a91b2c3d-4e5f-4a1b-8c2d-3e4f5a6b7c8d',
                        entity_name: 'vouchers',
                        record_id: 'REC-4109',
                        operation: 'INSERT',
                        type: 'cash_voucher',
                        priority: 'HIGH',
                        title: 'سند قبض نقدي #REC-4109',
                        summary: 'مؤسسة النيل للتجارة • 1,200,000 SDG',
                        payload: { voucherNo: 'REC-4109', beneficiaryName: 'مؤسسة النيل للتجارة', amountLocal: 1200000 }
                    }
                ];

                sampleInvoices.forEach(s => {
                    this.queue.unshift({
                        id: s.id,
                        entity_name: s.entity_name,
                        record_id: s.record_id,
                        operation: s.operation,
                        payload: JSON.stringify(s.payload),
                        status: 'PENDING',
                        retry_count: 0,
                        created_at: new Date().toISOString(),
                        type: s.type,
                        priority: s.priority,
                        title: s.title,
                        summary: s.summary,
                        synced_at: null,
                        lastError: null,
                        serverRef: null
                    });
                });

                this.saveQueue();
                this.renderUI();
                if (window.showModernToast) {
                    window.showModernToast('✨ تم توليد 3 معاملات أوفلاين في الطابور للتجربة الميدانية', 'success', 2500);
                }
            },

            renderUI() {
                const online = this.isOnline();
                const breakdown = this.getBreakdown();
                const pendingCount = breakdown.total;
                const syncingCount = this.queue.filter(q => String(q.status).toUpperCase() === 'SYNCING').length;
                const syncedCount = this.queue.filter(q => String(q.status).toUpperCase() === 'SYNCED').length;
                const conflictCount = this.queue.filter(q => String(q.status).toUpperCase() === 'FAILED' || String(q.status).toUpperCase() === 'CONFLICT').length;

                // 1. Header Outbox Drain Button & Red Counter Badge (جوار البحث والسمات)
                const headerOutboxBtn = document.getElementById('btn-header-outbox');
                const headerOutboxBadge = document.getElementById('header-outbox-badge');
                const headerOutboxIcon = document.getElementById('header-outbox-icon');

                if (headerOutboxBtn && headerOutboxBadge) {
                    if (this.isSyncing) {
                        headerOutboxBtn.className = 'header-deck-pill pill-sync is-syncing-outbox';
                        if (headerOutboxIcon) headerOutboxIcon.className = 'fa-solid fa-rotate fa-spin';
                        headerOutboxBadge.style.display = 'flex';
                        headerOutboxBadge.innerText = '⟳';
                        headerOutboxBtn.title = 'جاري تفريغ الطابور ومزامنة المعاملات مع السيرفر...';
                    } else if (pendingCount > 0) {
                        headerOutboxBtn.className = 'header-deck-pill pill-sync has-pending-outbox';
                        if (headerOutboxIcon) headerOutboxIcon.className = 'fa-solid fa-cloud-arrow-up';
                        headerOutboxBadge.style.display = 'flex';
                        headerOutboxBadge.innerText = pendingCount;
                        headerOutboxBtn.title = `${pendingCount} معاملات أوفلاين بانتظار التفريغ (${breakdown.vouchers} مالية، ${breakdown.sales} مبيعات) — اضغط للتفريغ الآن`;
                    } else {
                        headerOutboxBtn.className = 'header-deck-pill pill-sync';
                        if (headerOutboxIcon) headerOutboxIcon.className = 'fa-solid fa-cloud-arrow-up';
                        headerOutboxBadge.style.display = 'none';
                        headerOutboxBtn.title = online ? 'طابور الأوفلاين مفرغ بالكامل ومؤكد بالسحابة (Online)' : 'دون اتصال (Offline) — لا توجد معاملات معلقة';
                    }
                }

                // 2. Row 1 Live Internet Status Dot (نقطة خضراء متصل / نقطة حمراء منقطع)
                if (typeof window.syncMagaieesNetUI === 'function') {
                    window.syncMagaieesNetUI(online);
                } else {
                    const headerNetDot = document.getElementById('header-net-dot');
                    const headerNetWrap = document.getElementById('header-net-indicator');
                    if (headerNetDot) headerNetDot.className = online ? 'net-status-dot online' : 'net-status-dot offline';
                    if (headerNetWrap) headerNetWrap.className = online ? 'flagship-top-tile flagship-brand-tile online' : 'flagship-top-tile flagship-brand-tile offline';
                }

                // Bottom Docked connection indicator (if present)
                const headerPill = document.getElementById('btn-outbox-status');
                const pillDot = document.getElementById('outbox-pill-dot');
                const pillText = document.getElementById('outbox-pill-text');
                if (headerPill && pillDot) {
                    const statusClass = !online ? 'offline' : (this.isSyncing ? 'syncing' : 'online');
                    headerPill.className = `outbox-status-pill ${statusClass}`;
                    pillDot.className = `outbox-dot ${statusClass}`;
                    if (pillText) {
                        pillText.innerText = !online ? 'أوفلاين' : (this.isSyncing ? 'مزامنة ⚡' : 'متصل');
                    }
                    headerPill.title = !online 
                        ? `انقطع النت (النور أحمر) — البرنامج في وضع الأوفلاين والسندات تُحفظ محلياً (${pendingCount} معلق)` 
                        : (this.isSyncing 
                            ? 'جاري المزامنة اللحظية مع السيرفر ⚡' 
                            : `متصل بالسحابة (النور أخضر) • استجابة الشبكة: ${this.lastHeartbeatMs || 24}ms`);
                }

                // 3. Outbox Sheet Breakdown Elements
                const elVouchers = document.getElementById('outbox-count-vouchers');
                const elSales = document.getElementById('outbox-count-sales');
                const elOthers = document.getElementById('outbox-count-others');
                const elTotalPending = document.getElementById('outbox-total-pending-label');
                if (elVouchers) elVouchers.innerText = breakdown.vouchers;
                if (elSales) elSales.innerText = breakdown.sales;
                if (elOthers) elOthers.innerText = breakdown.others;
                if (elTotalPending) elTotalPending.innerText = `${pendingCount} معلقة`;

                // 4. Outbox Sheet Stats Grid Counters
                const elPending = document.getElementById('outbox-stat-pending');
                const elSyncing = document.getElementById('outbox-stat-syncing');
                const elSynced = document.getElementById('outbox-stat-synced');
                const elConflicts = document.getElementById('outbox-stat-conflicts');

                if (elPending) elPending.innerText = pendingCount;
                if (elSyncing) elSyncing.innerText = syncingCount;
                if (elSynced) elSynced.innerText = syncedCount;
                if (elConflicts) elConflicts.innerText = conflictCount;

                // 5. Banner Status
                const bannerDot = document.getElementById('outbox-banner-dot');
                const bannerTitle = document.getElementById('outbox-banner-title');
                const bannerSub = document.getElementById('outbox-banner-sub');
                const btnSimOffline = document.getElementById('btn-toggle-sim-offline');

                if (bannerDot && bannerTitle && bannerSub && btnSimOffline) {
                    bannerDot.className = `outbox-dot ${!online ? 'offline' : 'online'}`;
                    if (!online) {
                        bannerTitle.innerText = this.isSimulatedOffline ? 'وضع انقطاع الشبكة (محاكاة نشطة)' : 'الاتصال بالسحابة: غير متصل (Offline)';
                        bannerSub.innerText = pendingCount > 0 ? `يوجد (${pendingCount}) معاملات محفوظة محلياً بانتظار عودة الشبكة` : 'يتم حفظ المعاملات محلياً وتأجيل الرفع تلقائياً';
                        btnSimOffline.innerText = 'إلغاء المحاكاة (اتصال)';
                        btnSimOffline.style.background = 'rgba(239, 68, 94, 0.2)';
                        btnSimOffline.style.color = 'var(--rose)';
                    } else {
                        bannerTitle.innerText = pendingCount > 0 ? `متصل بالسحابة — يوجد (${pendingCount}) حركات قيد التفريغ` : 'الاتصال بالسحابة: متصل ومستقر';
                        bannerSub.innerText = pendingCount > 0 ? 'جاري تفريغ الطابور تلقائياً وربط الأرقام التسلسلية' : 'جميع المعاملات مؤكدة في السيرفر المركزي • الاستجابة: 24ms';
                        btnSimOffline.innerText = 'محاكاة انقطاع الشبكة';
                        btnSimOffline.style.background = 'var(--surface-sub)';
                        btnSimOffline.style.color = 'var(--text-main)';
                    }
                }

                // 6. Queue List Container
                const container = document.getElementById('outbox-queue-container');
                if (!container) return;

                if (this.queue.length === 0) {
                    container.innerHTML = `
                        <div style="text-align:center; padding:24px 12px; color:var(--text-muted); font-size:0.78rem;">
                            <i class="fa-solid fa-cloud-check" style="font-size:1.8rem; color:var(--emerald); opacity:0.8; margin-bottom:8px; display:block;"></i>
                            <strong>طابور sync_queue نظيف تماماً</strong>
                            <div style="font-size:0.7rem; margin-top:2px;">لا توجد معاملات مؤجلة بانتظار الإرسال للسحابة</div>
                        </div>
                    `;
                    return;
                }

                let html = '';
                this.queue.forEach(item => {
                    const st = String(item.status).toUpperCase();
                    let badgeClass = 'status-pending';
                    let statusLabel = '⏳ PENDING';
                    let statusColor = 'var(--amber)';

                    if (st === 'SYNCING') {
                        badgeClass = 'status-syncing';
                        statusLabel = '🔄 SYNCING...';
                        statusColor = 'var(--primary)';
                    } else if (st === 'SYNCED') {
                        badgeClass = 'status-synced';
                        statusLabel = '✅ SYNCED';
                        statusColor = 'var(--emerald)';
                    } else if (st === 'FAILED' || st === 'CONFLICT') {
                        badgeClass = 'status-conflict';
                        statusLabel = '⚠️ FAILED';
                        statusColor = 'var(--rose)';
                    }

                    let typeIcon = 'fa-receipt';
                    const itemType = String(item.type || item.entity_name || '').toLowerCase();
                    if (itemType.includes('transfer')) typeIcon = 'fa-truck-fast';
                    else if (itemType.includes('audit')) typeIcon = 'fa-clipboard-check';
                    else if (itemType.includes('voucher') || itemType.includes('payment') || itemType.includes('receipt') || itemType.includes('cash')) typeIcon = 'fa-money-bill-wave';
                    else if (itemType.includes('sale')) typeIcon = 'fa-cart-shopping';
                    else if (itemType.includes('approval')) typeIcon = 'fa-shield-halved';

                    html += `
                        <div class="outbox-queue-item ${badgeClass}">
                            <div style="display:flex; align-items:center; gap:8px;">
                                <div style="width:32px; height:32px; border-radius:8px; background:var(--surface-sub); display:flex; align-items:center; justify-content:center; color:var(--primary); font-size:0.85rem;">
                                    <i class="fa-solid ${typeIcon}"></i>
                                </div>
                                <div>
                                    <div style="font-size:0.78rem; font-weight:800; color:var(--text-main);">${item.title || item.record_id}</div>
                                    <div style="font-size:0.78rem; color:var(--text-muted);">${item.summary || item.entity_name}</div>
                                    <div style="font-size:0.75rem; font-family:'Inter',monospace; color:var(--text-muted); margin-top:2px; opacity:0.85;">
                                        <span style="color:var(--primary); font-weight:700;">[${item.entity_name || 'invoices'}:${item.operation || 'INSERT'}]</span> 
                                        ${item.id.slice(0, 18)}...
                                        ${item.serverRef ? `• <span style="color:var(--emerald); font-weight:700;">${item.serverRef}</span>` : ''}
                                    </div>
                                </div>
                            </div>
                            <div style="text-align:left;">
                                <span style="display:inline-block; font-size:0.76rem; font-weight:800; color:${statusColor}; background:var(--surface-sub); border:1px solid var(--border-glass); padding:2px 6px; border-radius:6px; margin-bottom:4px;">
                                    ${statusLabel}
                                </span>
                                <div style="font-size:0.75rem; font-family:'Inter',sans-serif; color:var(--text-muted); direction:ltr; text-align:right;">
                                    ${item.created_at ? item.created_at.slice(11, 16) : ''}
                                </div>
                            </div>
                        </div>
                    `;
                });

                container.innerHTML = html;
            }
        };

        // ═════════════════════════════════════════════════════════════════
        // KEYBOARD-AWARE FLUID VIEWPORT ENGINE
        // ═════════════════════════════════════════════════════════════════
        function setupFluidKeyboardViewport() {
            // When entering amounts/quantities, input fields automatically scroll into clear view without hiding the primary action button
            document.addEventListener('focusin', (e) => {
                const target = e.target;
                if (!target || !['INPUT', 'SELECT', 'TEXTAREA'].includes(target.tagName)) return;
                const sheet = target.closest('.mobile-bottom-sheet');
                if (!sheet) return;
                setTimeout(() => {
                    const sheetBody = target.closest('.sheet-body');
                    const pinnedFooter = sheet.querySelector('.pos-settlement-footer, .tx-submit-bar');
                    if (sheetBody) {
                        const targetRect = target.getBoundingClientRect();
                        const footerHeight = pinnedFooter ? pinnedFooter.offsetHeight : 70;
                        const visibleBottom = window.innerHeight - footerHeight;
                        if (targetRect.bottom > visibleBottom || targetRect.top < 60) {
                            target.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }
                    }
                }, 280);
            });
        }

        // Initialize on DOM load
        document.addEventListener('DOMContentLoaded', () => {
            initTheme();
            updateMuteToastsUI(isToastsMuted());
            window.magaieesToastsMuted = isToastsMuted();
            runLiveHardwareCalibration(false);
            if (typeof calibrateMobileScreen === 'function') calibrateMobileScreen(false);
            setupFluidKeyboardViewport();
            
            const savedBranchLabel = localStorage.getItem('magaiees_branch_label');
            const savedBranchKey = localStorage.getItem('magaiees_branch');
            if (savedBranchLabel && savedBranchKey) {
                const headerEl = document.getElementById('header-branch-name');
                if (headerEl) headerEl.innerText = savedBranchLabel;
                const tagEl = document.getElementById('inventory-branch-tag');
                if (tagEl) tagEl.innerText = savedBranchLabel;
                document.querySelectorAll('.branch-option').forEach(el => el.classList.remove('active'));
                const activeOpt = document.getElementById('branch-opt-' + savedBranchKey);
                if (activeOpt) activeOpt.classList.add('active');
            }

            RuleAlertEngine.init();
            refreshMobileData();
            if (window.OfflineOutboxEngine) window.OfflineOutboxEngine.init();

            const savedTab = sessionStorage.getItem('magaiees_active_tab') || 'dashboard';
            switchMobileTab(savedTab);

            // Show voice button only if Speech API is supported
            if (VoiceCommandEngine.isSupported()) {
                const vBtn = document.getElementById('voice-hub-btn');
                if (vBtn) vBtn.style.display = '';
            }
        });
    
        // ═════════════════════════════════════════════════════════════════
        // 🖨️ UNIVERSAL PRINT ENGINE (طباعة حرارية لجميع السندات والعمليات)
        // ═════════════════════════════════════════════════════════════════
        window.UniversalPrintEngine = {
            printVoucher(v) {
                if (!v) return;
                triggerHaptic('light');
                const paper = document.getElementById('thermal-receipt-content');
                if (!paper) return;

                const vNum = v.voucherNo || v.paymentNo || v.receiptNo || v.voucher_no || v.id || '#TX-1';
                const amt = parseFloat(v.amountLocal || v.amount || v.total || 0);
                const amtForeign = parseFloat(v.amountForeign || 0);
                const txDate = v.date || new Date().toISOString().split('T')[0];
                const txTime = v.time || new Date().toLocaleTimeString('ar-SD', { hour: '2-digit', minute: '2-digit' });
                const fromName = (typeof v.fromAccount === 'object' ? v.fromAccount.name : v.fromAccount) || v.from_account || v.customerName || v.customer || 'الخزينة الرئيسية';
                const toName = (typeof v.toAccount === 'object' ? v.toAccount.name : v.toAccount) || v.to_account || v.recipient || v.partnerName || 'الحساب المستلم';
                const notes = v.notes || v.statement || 'حركة مالية معتمدة';
                const isReceipt = v.type === 'receipt' || (String(vNum).startsWith('R') || String(vNum).startsWith('IN-'));
                const typeTitle = isReceipt ? 'سند قبض واستلام مالي' : 'سند صرف ودفع مالي';
                const refNo = v.reference || v.refNo || v.transferNo || v.mobileTransferNo || '---';

                paper.innerHTML = `
                    <div class="thermal-header">
                        <h3>مؤسسة الصجانة التجارية</h3>
                        <p>سوق السجانة لمواد البناء والأخشاب - الخرطوم</p>
                        <p>هاتف: +249 91 234 5678</p>
                        <div class="thermal-divider"></div>
                        <h4>${typeTitle}</h4>
                        <p style="font-family:monospace; font-weight:900; font-size:1.15rem; margin-top:2px;">#${vNum}</p>
                        <div style="display:inline-block; background:#059669; color:#ffffff; font-size:0.72rem; font-weight:900; padding:2px 10px; border-radius:6px; margin-top:4px;">
                            ✅ معتمد بالسيرفر
                        </div>
                    </div>
                    <div class="thermal-divider"></div>
                    <div class="thermal-row">
                        <span>التاريخ والوقت:</span>
                        <span>${txDate} ${txTime}</span>
                    </div>
                    <div class="thermal-row">
                        <span>من حساب (الصارف):</span>
                        <strong>${fromName}</strong>
                    </div>
                    <div class="thermal-row">
                        <span>إلى حساب (المستلم):</span>
                        <strong>${toName}</strong>
                    </div>
                    ${v.beneficiaryName ? `
                    <div class="thermal-row">
                        <span>المستفيد / المسلم:</span>
                        <span>${v.beneficiaryName}</span>
                    </div>` : ''}
                    <div class="thermal-row">
                        <span>طريقة الدفع:</span>
                        <span>${v.paymentMethod === 'bank' ? 'تحويل بنكي / بنكك' : (v.paymentMethod === 'cheque' ? 'شيك مصرفي' : 'نقداً (كاش)')}</span>
                    </div>
                    <div class="thermal-row">
                        <span>رقم المرجع / الإشعار:</span>
                        <span style="font-family:monospace; font-weight:800;">${refNo}</span>
                    </div>
                    <div class="thermal-divider"></div>
                    <div class="thermal-total-row">
                        <span>المبلغ الصافي:</span>
                        <span>${fmt(amt)} SDG</span>
                    </div>
                    ${amtForeign > 0 ? `
                    <div class="thermal-row" style="color:#0284c7; font-weight:800;">
                        <span>المقابل الأجنبي ($):</span>
                        <span>$${fmt(amtForeign)}</span>
                    </div>` : ''}
                    <div class="thermal-divider"></div>
                    <div class="thermal-row" style="font-size:0.76rem; color:#444;">
                        <span>البيان:</span>
                        <span>${notes}</span>
                    </div>
                    <div class="thermal-divider"></div>
                    <div style="display:grid; grid-template-columns: 1fr 1fr; gap:10px; text-align:center; font-size:0.75rem; margin-top:10px;">
                        <div>
                            <div>توقيع الصارف / المحاسب</div>
                            <div style="border-bottom:1px solid #000; height:30px; margin-top:5px;"></div>
                        </div>
                        <div>
                            <div>توقيع المستلم</div>
                            <div style="border-bottom:1px solid #000; height:30px; margin-top:5px;"></div>
                        </div>
                    </div>
                    <div class="thermal-footer" style="margin-top:12px;">
                        <div style="font-family:monospace; letter-spacing:2px; font-size:1.1rem;">*${vNum}*</div>
                        <div style="font-size:0.76rem; color:#555; margin-top:4px;">
                            نظام مقاييس المحاسبي 2026 • معتمد سحابياً ومحلياً
                        </div>
                    </div>
                `;
                openBottomSheet('sheet-receipt-print');
            },

            printTransactionsReport() {
                triggerHaptic('light');
                const paper = document.getElementById('thermal-receipt-content');
                if (!paper) return;
                let listHtml = '';
                let totalIn = 0;
                let totalOut = 0;
                (M_TRANSACTIONS || []).slice(0, 30).forEach(tx => {
                    const a = parseFloat(tx.amount || tx.total || 0);
                    const isRec = tx.type === 'receipt' || tx.type === 'sale';
                    if (isRec) totalIn += a; else totalOut += a;
                    listHtml += `
                        <div class="thermal-row" style="font-size:0.74rem;">
                            <span>#${tx.voucher_no || tx.id} (${(tx.to_account || tx.from_account || 'حركة').slice(0, 14)})</span>
                            <span style="font-weight:800; color:${isRec ? '#059669' : '#dc2626'};">${isRec ? '+' : '-'}${fmt(a)}</span>
                        </div>
                    `;
                });

                paper.innerHTML = `
                    <div class="thermal-header">
                        <h3>مؤسسة الصجانة التجارية</h3>
                        <p>كشف العمليات الميدانية السريع</p>
                        <div class="thermal-divider"></div>
                        <h4>ملخص الحركات اليومية</h4>
                        <p>${new Date().toLocaleDateString('ar-SD')} - ${new Date().toLocaleTimeString('ar-SD')}</p>
                    </div>
                    <div class="thermal-divider"></div>
                    ${listHtml}
                    <div class="thermal-divider"></div>
                    <div class="thermal-row" style="color:#059669; font-weight:900;">
                        <span>إجمالي المقبوضات (+):</span>
                        <span>+${fmt(totalIn)} SDG</span>
                    </div>
                    <div class="thermal-row" style="color:#dc2626; font-weight:900;">
                        <span>إجمالي المدفوعات (-):</span>
                        <span>-${fmt(totalOut)} SDG</span>
                    </div>
                    <div class="thermal-total-row">
                        <span>صافي التدفق:</span>
                        <span>${fmt(totalIn - totalOut)} SDG</span>
                    </div>
                `;
                openBottomSheet('sheet-receipt-print');
            }
        };

        // ═════════════════════════════════════════════════════════════════
        // 🛒 PURCHASE ENGINE (إدارة فواتير الشراء والتوريد السريعة)
        // ═════════════════════════════════════════════════════════════════
        window.PurchaseEngine = {
            newInvoice() {
                triggerHaptic('success');
                const itemSel = document.getElementById('purchase-item');
                const qtyInp = document.getElementById('purchase-qty');
                const priceInp = document.getElementById('purchase-price');
                const totalDisp = document.getElementById('purchase-total-display');
                if (itemSel) itemSel.selectedIndex = 0;
                if (qtyInp) qtyInp.value = '1';
                if (priceInp) priceInp.value = '';
                if (totalDisp) totalDisp.textContent = '0 SDG';
                if (window.showModernToast) window.showModernToast('✨ فتح فاتورة شراء وتوريد جديدة', 'success', 2000);
            },
            saveInvoice() {
                const form = document.querySelector('#sheet-purchase form');
                if (form) {
                    if (form.requestSubmit) form.requestSubmit();
                    else form.dispatchEvent(new Event('submit', { cancelable: true }));
                }
            },
            editInvoice() {
                triggerHaptic('medium');
                const purchases = (typeof loadTenantArray === 'function') ? (loadTenantArray('erp_purchase_invoices_v1') || []) : [];
                if (purchases.length === 0) {
                    if (window.showModernToast) window.showModernToast('لا توجد فواتير شراء سابقة للتعديل', 'info', 2000);
                    return;
                }
                const q = prompt('🔍 أدخل رقم فاتورة الشراء أو اسم المورد للتعديل:\nآخر فاتورة: ' + (purchases[0].invoiceNo || purchases[0].id));
                if (!q || !q.trim()) return;
                const p = purchases.find(x => `${x.invoiceNo || ''} ${x.id || ''} ${x.supplier || ''}`.toLowerCase().includes(q.trim().toLowerCase()));
                if (p) {
                    const qtyInp = document.getElementById('purchase-qty');
                    const priceInp = document.getElementById('purchase-price');
                    if (qtyInp && p.qty) qtyInp.value = p.qty;
                    if (priceInp && p.price) priceInp.value = p.price;
                    if (typeof calculatePurchaseTotal === 'function') calculatePurchaseTotal();
                    if (window.showModernToast) window.showModernToast('✏️ تم استدعاء بيانات فاتورة الشراء للتعديل', 'warning', 2000);
                } else {
                    alert('لم يتم العثور على فاتورة شراء بهذا الرقم');
                }
            },
            deleteInvoice() {
                triggerHaptic('heavy');
                if (!confirm('⚠️ هل أنت متأكد من إلغاء وتفريغ فاتورة الشراء الحالية؟')) return;
                this.newInvoice();
                if (window.showModernToast) window.showModernToast('🗑️ تم تفريغ فاتورة الشراء', 'success', 2000);
            },
            printInvoice() {
                triggerHaptic('medium');
                const totalDisp = document.getElementById('purchase-total-display')?.textContent || '0 SDG';
                const supp = document.getElementById('purchase-supplier')?.value || 'مورد نقدي عام';
                const item = document.getElementById('purchase-item');
                const itemName = item && item.selectedIndex > 0 ? item.options[item.selectedIndex].text : 'صنف مشتريات';
                const qty = document.getElementById('purchase-qty')?.value || '1';
                const price = document.getElementById('purchase-price')?.value || '0';

                const paper = document.getElementById('thermal-receipt-content');
                if (!paper) return;
                paper.innerHTML = `
                    <div class="thermal-header">
                        <h3>مؤسسة الصجانة التجارية</h3>
                        <p>إذن توريد وفاتورة مشتريات مخزنية</p>
                        <div class="thermal-divider"></div>
                        <h4>فاتورة شراء بضاعة</h4>
                        <p style="font-family:monospace; font-weight:900;">#PUR-${new Date().toISOString().slice(2,7).replace('-','')}-${Date.now().toString().slice(-4)}</p>
                    </div>
                    <div class="thermal-divider"></div>
                    <div class="thermal-row"><span>المورد:</span><strong>${supp}</strong></div>
                    <div class="thermal-row"><span>الصنف المورّد:</span><strong>${itemName}</strong></div>
                    <div class="thermal-row"><span>الكمية:</span><span>${qty}</span></div>
                    <div class="thermal-row"><span>سعر الوحدة:</span><span>${fmt(price)} SDG</span></div>
                    <div class="thermal-divider"></div>
                    <div class="thermal-total-row"><span>الإجمالي:</span><span>${totalDisp}</span></div>
                    <div class="thermal-footer" style="margin-top:10px;">
                        <p>توقيع أمين المستودع والمستلم</p>
                        <div style="border-bottom:1px solid #000; height:30px;"></div>
                    </div>
                `;
                openBottomSheet('sheet-receipt-print');
            },
            searchInvoice() {
                this.editInvoice();
            },
            shareInvoice() {
                const totalDisp = document.getElementById('purchase-total-display')?.textContent || '0 SDG';
                const text = `📦 *فاتورة شراء وتوريد - مؤسسة السجانة*\nالمبلغ الإجمالي: ${totalDisp}\nالتاريخ: ${new Date().toLocaleDateString('ar-SD')}`;
                window.open('https://api.whatsapp.com/send?text=' + encodeURIComponent(text), '_blank');
            },
            resetForm() {
                this.newInvoice();
            },
            navigate(dir) {
                this.editInvoice();
            }
        };

        // ═════════════════════════════════════════════════════════════════
        // ⚡ UNIVERSAL ACTION ENGINE (المحرك الموحد لجميع أزرار شاشات الجوال)
        // [جديد] [حفظ] [تعديل] [حذف] [طباعة] [بحث] [مشاركة] [تراجع]
        // ═════════════════════════════════════════════════════════════════
        window.UniversalActionEngine = {
            dispatch(action, screen) {
                triggerHaptic('light');
                switch(action) {
                    case 'new':
                        this.new(screen);
                        break;
                    case 'save':
                        this.save(screen);
                        break;
                    case 'edit':
                        this.edit(screen);
                        break;
                    case 'delete':
                        this.delete(screen);
                        break;
                    case 'print':
                        this.print(screen);
                        break;
                    case 'search':
                        this.search(screen);
                        break;
                    case 'share':
                        this.share(screen);
                        break;
                    case 'cancel':
                        this.cancel(screen);
                        break;
                    case 'refresh':
                        if (typeof refreshMobileData === 'function') refreshMobileData(true);
                        break;
                }
            },

            navigate(screen, direction) {
                triggerHaptic('light');
                if (screen === 'financial-tx') {
                    if (direction === 'first') VoucherNavigator.first();
                    else if (direction === 'prev') VoucherNavigator.prev();
                    else if (direction === 'next') VoucherNavigator.next();
                    else if (direction === 'last') VoucherNavigator.last();
                } else if (screen === 'sale') {
                    MobilePOS.navigate(direction);
                } else if (screen === 'purchase') {
                    PurchaseEngine.navigate(direction);
                } else if (screen === 'stock-transfer') {
                    if (direction === 'first' && typeof StockTransferEngine.loadTransferWaybill === 'function') StockTransferEngine.loadTransferWaybill(0);
                    else if (direction === 'last' && typeof StockTransferEngine.loadTransferWaybill === 'function') StockTransferEngine.loadTransferWaybill(-1);
                }
            },

            new(screen) {
                if (screen === 'financial-tx') {
                    openFinancialTxSheet('transfer');
                    VoucherNavigator.newVoucher();
                } else if (screen === 'sale') {
                    openBottomSheet('sheet-sale');
                    MobilePOS.newInvoice();
                } else if (screen === 'purchase') {
                    openBottomSheet('sheet-purchase');
                    PurchaseEngine.newInvoice();
                } else if (screen === 'stock-transfer') {
                    openBottomSheet('sheet-stock-transfer');
                    if (typeof StockTransferEngine.newTransfer === 'function') StockTransferEngine.newTransfer();
                } else if (screen === 'item-audit') {
                    openBottomSheet('sheet-item-audit');
                } else if (screen === 'statement') {
                    openFinancialTxSheet('transfer');
                } else if (screen === 'transactions' || screen === 'dashboard') {
                    openFinancialTxSheet('transfer');
                    VoucherNavigator.newVoucher();
                } else if (screen === 'ledgers') {
                    openFinancialTxSheet('transfer');
                } else if (screen === 'inventory') {
                    openBottomSheet('sheet-purchase');
                } else if (screen === 'approvals') {
                    openBottomSheet('sheet-rule-settings');
                }
            },

            save(screen) {
                if (screen === 'financial-tx') {
                    handleFinancialTxSubmit(null, false);
                } else if (screen === 'sale') {
                    MobilePOS.submitSale(false, false);
                } else if (screen === 'purchase') {
                    PurchaseEngine.saveInvoice();
                } else if (screen === 'stock-transfer') {
                    StockTransferEngine.saveDraft();
                } else if (screen === 'item-audit') {
                    InventoryEngine.submitAuditReconciliation();
                } else if (screen === 'statement') {
                    if (typeof LedgerEngine.openPdfStatementPreview === 'function') LedgerEngine.openPdfStatementPreview();
                } else {
                    if (window.DualNumberingEngine && typeof window.DualNumberingEngine.triggerSyncQueuePush === 'function') {
                        window.DualNumberingEngine.triggerSyncQueuePush();
                    } else if (typeof refreshMobileData === 'function') {
                        refreshMobileData(true);
                    }
                    if (window.showModernToast) window.showModernToast('💾 جاري حفظ ومزامنة كافة السجلات مع السيرفر الحي...', 'success', 2200);
                }
            },

            edit(screen) {
                if (screen === 'financial-tx') {
                    VoucherNavigator.enableEdit();
                } else if (screen === 'sale') {
                    MobilePOS.editInvoicePrompt();
                } else if (screen === 'purchase') {
                    PurchaseEngine.editInvoice();
                } else if (screen === 'stock-transfer') {
                    if (typeof StockTransferEngine.openTransferSheet === 'function') StockTransferEngine.openTransferSheet();
                } else if (screen === 'item-audit') {
                    const physicalInp = document.getElementById('audit-physical-input');
                    if (physicalInp) { physicalInp.focus(); physicalInp.select(); }
                } else if (screen === 'statement') {
                    const sel = document.getElementById('statement-customer-select');
                    if (sel) sel.focus();
                } else if (screen === 'transactions') {
                    if (M_TRANSACTIONS && M_TRANSACTIONS.length > 0) {
                        this.editItem('transactions', M_TRANSACTIONS[0]);
                    } else {
                        if (window.showModernToast) window.showModernToast('لا توجد حركات للتعديل', 'info', 2000);
                    }
                } else if (screen === 'inventory') {
                    InventoryEngine.openQuickAudit();
                } else {
                    if (window.showModernToast) window.showModernToast('✏️ حدد عنصراً لتعديله', 'info', 2000);
                }
            },

            editItem(screen, item) {
                if (!item) return;
                triggerHaptic('medium');
                const vNum = item.voucher_no || item.id || item.invoice_no;
                openFinancialTxSheet('transfer');
                setTimeout(() => {
                    if (window.VoucherNavigator && Array.isArray(window.VoucherNavigator.vouchers)) {
                        const idx = window.VoucherNavigator.vouchers.findIndex(v => (v.voucherNo || v.id) == vNum);
                        if (idx >= 0) {
                            window.VoucherNavigator.currentIndex = idx;
                            window.VoucherNavigator.displayVoucher(idx);
                        } else {
                            window.VoucherNavigator.displayVoucherObject(item);
                        }
                        window.VoucherNavigator.enableEdit();
                    }
                }, 300);
            },

            delete(screen) {
                if (screen === 'financial-tx') {
                    VoucherNavigator.deleteCurrentVoucher();
                } else if (screen === 'sale') {
                    MobilePOS.deleteCurrentInvoice();
                } else if (screen === 'purchase') {
                    PurchaseEngine.deleteInvoice();
                } else if (screen === 'stock-transfer') {
                    if (typeof StockTransferEngine.resetBasket === 'function') StockTransferEngine.resetBasket();
                } else if (screen === 'item-audit') {
                    closeBottomSheet('sheet-item-audit');
                } else if (screen === 'transactions') {
                    if (M_TRANSACTIONS && M_TRANSACTIONS.length > 0) {
                        this.deleteItem('transactions', M_TRANSACTIONS[0]);
                    }
                }
            },

            async deleteItem(screen, item) {
                if (!item) return;
                triggerHaptic('heavy');
                const vNum = item.voucher_no || item.id;
                const amt = item.amount || item.total || 0;
                if (!confirm(`⚠️ هل أنت متأكد من حذف الحركة [${vNum}] بمبلغ [${fmt(amt)} SDG]؟ لا يمكن التراجع.`)) return;

                try {
                    await fetch('mobile-dashboard.php?action=delete_voucher', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ voucherNo: vNum, id: vNum })
                    });
                } catch(e) {
                    console.warn(e);
                }

                ['erp_financial_txs_v1', 'erp_single_payments_v1', 'erp_single_receipts_v1', 'erp_sales_invoices_v1'].forEach(k => {
                    if (typeof loadTenantArray === 'function' && typeof saveTenantArray === 'function') {
                        let arr = loadTenantArray(k) || [];
                        const origLen = arr.length;
                        arr = arr.filter(x => (x.voucherNo || x.id || x.invoiceNo) != vNum);
                        if (arr.length !== origLen) saveTenantArray(k, arr);
                    }
                });

                if (typeof M_TRANSACTIONS !== 'undefined' && Array.isArray(M_TRANSACTIONS)) {
                    const idx = M_TRANSACTIONS.findIndex(x => (x.voucher_no || x.id) == vNum);
                    if (idx >= 0) M_TRANSACTIONS.splice(idx, 1);
                }

                if (window.VoucherNavigator && typeof window.VoucherNavigator.loadVouchers === 'function') {
                    window.VoucherNavigator.loadVouchers();
                }

                if (typeof renderTransactionsView === 'function') renderTransactionsView();
                if (window.showModernToast) window.showModernToast(`🗑️ تم حذف الحركة [${vNum}] بنجاح`, 'success', 2200);
            },

            print(screen) {
                if (screen === 'financial-tx') {
                    VoucherNavigator.printCurrentVoucher();
                } else if (screen === 'sale') {
                    MobilePOS.printThermalDirect();
                } else if (screen === 'purchase') {
                    PurchaseEngine.printInvoice();
                } else if (screen === 'stock-transfer') {
                    StockTransferEngine.printThermalWaybill();
                } else if (screen === 'item-audit') {
                    const itemName = document.getElementById('audit-item-name')?.textContent || 'صنف';
                    const sku = document.getElementById('audit-item-sku')?.textContent || 'SKU';
                    const stock = document.getElementById('audit-system-stock')?.textContent || '0';
                    alert(`🖨️ طباعة بطاقة الصنف:\n${itemName} (${sku})\nالرصيد: ${stock}`);
                } else if (screen === 'statement') {
                    if (typeof LedgerEngine.openPdfStatementPreview === 'function') LedgerEngine.openPdfStatementPreview();
                } else if (screen === 'transactions') {
                    UniversalPrintEngine.printTransactionsReport();
                } else {
                    window.print();
                }
            },

            printItem(screen, item) {
                if (!item) return;
                UniversalPrintEngine.printVoucher(item);
            },

            search(screen) {
                if (screen === 'financial-tx') {
                    VoucherNavigator.searchPrompt();
                } else if (screen === 'sale') {
                    MobilePOS.searchInvoice();
                } else if (screen === 'purchase') {
                    PurchaseEngine.searchInvoice();
                } else if (screen === 'transactions') {
                    const inp = document.getElementById('tx-view-search-input');
                    if (inp) { inp.focus(); inp.scrollIntoView({ behavior: 'smooth' }); }
                } else if (screen === 'inventory') {
                    const inp = document.getElementById('inventory-search-input');
                    if (inp) { inp.focus(); inp.scrollIntoView({ behavior: 'smooth' }); }
                } else if (screen === 'ledgers') {
                    const inp = document.getElementById('picker-search-input') || document.getElementById('statement-customer-select');
                    if (inp) { inp.focus(); }
                } else {
                    openBottomSheet('sheet-global-search');
                }
            },

            share(screen) {
                if (screen === 'financial-tx') {
                    handleTxWhatsAppShareClick();
                } else if (screen === 'sale') {
                    MobilePOS.shareThermalWhatsApp();
                } else if (screen === 'purchase') {
                    PurchaseEngine.shareInvoice();
                } else if (screen === 'stock-transfer') {
                    StockTransferEngine.shareWaybillWhatsApp();
                } else if (screen === 'statement') {
                    const sel = document.getElementById('statement-customer-select');
                    if (sel && sel.value && typeof sendStatementWhatsApp === 'function') {
                        sendStatementWhatsApp();
                    } else {
                        if (window.showModernToast) window.showModernToast('اختر عميلاً أولاً لمشاركة كشف الحساب', 'info', 2000);
                    }
                } else {
                    if (navigator.share) {
                        navigator.share({
                            title: 'مقاييس ERP - تقرير سريع',
                            text: 'تقرير العمليات الميدانية - مؤسسة السجانة التجارية',
                            url: window.location.href
                        }).catch(() => {});
                    } else {
                        window.open('https://api.whatsapp.com/send?text=' + encodeURIComponent('تقرير مقاييس ERP: ' + window.location.href), '_blank');
                    }
                }
            },

            cancel(screen) {
                if (screen === 'financial-tx') {
                    VoucherNavigator.cancelEdit();
                } else if (screen === 'sale') {
                    MobilePOS.clearCart();
                } else if (screen === 'purchase') {
                    PurchaseEngine.resetForm();
                } else if (screen === 'stock-transfer') {
                    if (typeof StockTransferEngine.resetBasket === 'function') StockTransferEngine.resetBasket();
                } else if (screen === 'item-audit') {
                    closeBottomSheet('sheet-item-audit');
                }
            }
        };
    
        // ═════════════════════════════════════════════════════════════════
        // 👁️ PRIVACY STEALTH SHIELD ENGINE (إخفاء الأرقام بنجوم)
        // ═════════════════════════════════════════════════════════════════
        let isStealthPrivacyActive = false;
        const originalTextValues = new WeakMap();

        function togglePrivacyStealthMode() {
            triggerHaptic('medium');
            isStealthPrivacyActive = !isStealthPrivacyActive;
            const btn = document.getElementById('btn-header-privacy');
            const icon = document.getElementById('privacy-eye-icon');
            const label = document.getElementById('privacy-eye-label');
            const toast = document.getElementById('privacy-stealth-toast');
            const toastText = document.getElementById('privacy-toast-text');

            const amountSelectors = [
                '.matrix-val', '.kpi-val', '.micro-val', '.activity-item .inter-font',
                '.cash-val', '.aging-val', '.quad-val', '.header-kpi-val',
                '.stat-num', '.total-val', '.vault-balance', '.balance-val'
            ];
            const amountNodes = document.querySelectorAll(amountSelectors.join(','));

            if (isStealthPrivacyActive) {
                if (btn) btn.classList.add('stealth-active');
                if (icon) icon.className = 'fa-solid fa-eye-slash';
                if (label) label.textContent = 'مخفي';

                amountNodes.forEach(node => {
                    if (!originalTextValues.has(node)) {
                        originalTextValues.set(node, node.innerText);
                    }
                    node.setAttribute('data-original-val', node.innerText);
                    node.innerText = '••••••';
                });

                if (toast && toastText) {
                    toastText.textContent = '🛡️ تم تفعيل وضع الخصوصية: تم إخفاء كافة الأرقام بالنجوم (••••••)';
                    toast.style.display = 'flex';
                    setTimeout(() => { toast.style.display = 'none'; }, 2500);
                }
            } else {
                if (btn) btn.classList.remove('stealth-active');
                if (icon) icon.className = 'fa-solid fa-eye';
                if (label) label.textContent = 'الخصوصية';

                amountNodes.forEach(node => {
                    const orig = originalTextValues.get(node) || node.getAttribute('data-original-val');
                    if (orig) node.innerText = orig;
                });

                if (toast && toastText) {
                    toastText.textContent = '👁️ تم إظهار الأرقام والمبالغ المالية';
                    toast.style.display = 'flex';
                    setTimeout(() => { toast.style.display = 'none'; }, 2200);
                }
            }
        }

        // ═════════════════════════════════════════════════════════════════
        // 🎙️ AI VOICE COPILOT ENGINE (محرك الصوت المحاسبي والاعتماد الفوري)
        // ═════════════════════════════════════════════════════════════════
        let voiceCopilotRecognition = null;
        let isVoiceCopilotListening = false;
        let currentVoiceCopilotData = null;

        function openAiVoiceCopilotModal() {
            triggerHaptic('light');
            openBottomSheet('sheet-ai-voice-copilot');
            resetVoiceCopilotUI();
        }

        function resetVoiceCopilotUI() {
            const status = document.getElementById('voice-copilot-status');
            const transcript = document.getElementById('voice-copilot-transcript');
            const card = document.getElementById('voice-copilot-approval-card');
            if (status) status.textContent = 'اضغط على المايك للتحدث باللغة العربية أو اختر أمراً جاهزاً:';
            if (transcript) transcript.textContent = 'بانتظار صوتك أو اختيارك...';
            if (card) card.style.display = 'none';
            stopVoiceWaveAnimation();
        }

        function startVoiceWaveAnimation() {
            document.querySelectorAll('#sheet-ai-voice-copilot .wave-bar').forEach(b => {
                b.style.animationPlayState = 'running';
            });
            const micBtn = document.getElementById('voice-copilot-mic-btn');
            if (micBtn) micBtn.style.boxShadow = '0 0 35px #22d3ee, 0 0 15px #a855f7';
        }

        function stopVoiceWaveAnimation() {
            document.querySelectorAll('#sheet-ai-voice-copilot .wave-bar').forEach(b => {
                b.style.animationPlayState = 'paused';
            });
            const micBtn = document.getElementById('voice-copilot-mic-btn');
            if (micBtn) micBtn.style.boxShadow = '0 0 30px rgba(168,85,247,0.7)';
        }

        function toggleVoiceCopilotListening() {
            triggerHaptic('medium');
            if (isVoiceCopilotListening) {
                if (voiceCopilotRecognition) voiceCopilotRecognition.stop();
                isVoiceCopilotListening = false;
                stopVoiceWaveAnimation();
                return;
            }

            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            if (!SpeechRecognition) {
                alert('المتصفح الحالي لا يدعم التعرف المباشر على الصوت من الميكروفون، يمكنك تجربة الأوامر النموذجية الجاهزة فوراً بالأسفل!');
                return;
            }

            try {
                voiceCopilotRecognition = new SpeechRecognition();
                voiceCopilotRecognition.lang = 'ar-SA';
                voiceCopilotRecognition.continuous = false;
                voiceCopilotRecognition.interimResults = true;

                voiceCopilotRecognition.onstart = () => {
                    isVoiceCopilotListening = true;
                    startVoiceWaveAnimation();
                    const status = document.getElementById('voice-copilot-status');
                    if (status) status.textContent = '🔴 جاري الاستماع لنبرة صوتك... تحدث باللغة العربية';
                };

                voiceCopilotRecognition.onresult = (event) => {
                    let text = '';
                    for (let i = event.resultIndex; i < event.results.length; ++i) {
                        text += event.results[i][0].transcript;
                    }
                    const tr = document.getElementById('voice-copilot-transcript');
                    if (tr) tr.textContent = text;
                    if (event.results[0].isFinal) {
                        parseVoiceAccountingIntent(text);
                    }
                };

                voiceCopilotRecognition.onerror = () => {
                    isVoiceCopilotListening = false;
                    stopVoiceWaveAnimation();
                };

                voiceCopilotRecognition.onend = () => {
                    isVoiceCopilotListening = false;
                    stopVoiceWaveAnimation();
                };

                voiceCopilotRecognition.start();
            } catch (e) {
                alert('يرجى التحقق من صلاحية الميكروفون بالمتصفح أو النقر على الأوامر الجاهزة.');
            }
        }

        function runPredefinedVoiceScenario(scenarioKey) {
            triggerHaptic('light');
            startVoiceWaveAnimation();
            const tr = document.getElementById('voice-copilot-transcript');
            const st = document.getElementById('voice-copilot-status');

            if (scenarioKey === 'sales_mohammed') {
                const phrase = 'أريد فاتورة مبيعات إلى العميل محمد حسن، 5 طن سكر ماستر، سعر الطن 650 دولار، نقداً من مخزن الخرطوم';
                if (tr) tr.textContent = phrase;
                if (st) st.textContent = '🟢 تم التقاط وتحليل أمر الفاتورة بالذكاء الاصطناعي:';
                setTimeout(() => { stopVoiceWaveAnimation(); parseVoiceAccountingIntent(phrase); }, 400);
            } else if (scenarioKey === 'disbursement_hams') {
                const phrase = 'أريد أن أصرف إلى همس مبلغ 70 ألف جنيه، رقم العملية 678 بتاريخ اليوم من الخزينة الرئيسية';
                if (tr) tr.textContent = phrase;
                if (st) st.textContent = '🟢 تم التقاط وتحليل سند الصرف بالذكاء الاصطناعي:';
                setTimeout(() => { stopVoiceWaveAnimation(); parseVoiceAccountingIntent(phrase); }, 400);
            } else if (scenarioKey === 'statement_nile') {
                const phrase = 'أعطني كشف حساب شركة النيل للاستيراد وموقف ديونها';
                if (tr) tr.textContent = phrase;
                if (st) st.textContent = '🟢 تم استخراج طلب كشف الحساب بالذكاء الاصطناعي:';
                setTimeout(() => { stopVoiceWaveAnimation(); parseVoiceAccountingIntent(phrase); }, 400);
            }
        }

        function parseVoiceAccountingIntent(text) {
            const lower = text.toLowerCase();
            let parsed = { type: 'unknown' };

            if (lower.includes('مبيعات') || lower.includes('فاتورة') || lower.includes('محمد حسن') || lower.includes('طن')) {
                parsed = {
                    type: 'sales',
                    title: 'فاتورة مبيعات - العميل محمد حسن',
                    partner: 'محمد حسن',
                    item: 'سكر ماستر (5 طن)',
                    unitPrice: '$650 / طن (30 ريال للوحدة)',
                    total: '$3,250 (9.1M SDG)',
                    warehouse: 'مستودع الخرطوم الرئيسي',
                    ref: '#1049'
                };
            } else if (lower.includes('صرف') || lower.includes('أصرف') || lower.includes('همس') || lower.includes('678') || lower.includes('جنيه')) {
                parsed = {
                    type: 'payment',
                    title: 'سند صرف نقدية مستعجل (#678)',
                    partner: 'همس للخدمات والترحيل',
                    amount: '70,000 ج.س ($250)',
                    total: '70,000 SDG',
                    account: 'الخزينة الرئيسية للإدارة',
                    notes: 'تفريغ ونقل شحنة استثنائية من المحطة',
                    ref: '#678'
                };
            } else {
                parsed = {
                    type: 'statement',
                    title: 'كشف حساب - شركة النيل للاستيراد',
                    partner: 'شركة النيل للاستيراد',
                    total: '$12,400 مدين (متأخر 35 يوماً)',
                    ref: 'كشف الأستاذ'
                };
            }

            currentVoiceCopilotData = parsed;
            renderVoiceApprovalCard(parsed);

            if ('speechSynthesis' in window) {
                let msg = '';
                if (parsed.type === 'sales') msg = 'تم تجهيز فاتورة مبيعات للعميل محمد حسن بإجمالي ثلاثة آلاف ومائتين وخمسين دولاراً، هل تعتمد الترحيل؟';
                else if (parsed.type === 'payment') msg = 'تم تجهيز سند صرف للطرف همس بمبلغ سبعين ألف جنيه برقم عملية 678، هل تعتمد الصرف؟';
                else msg = 'تم استخراج كشف الحساب المطلوب بنجاح';
                const utt = new SpeechSynthesisUtterance(msg);
                utt.lang = 'ar-SA';
                window.speechSynthesis.speak(utt);
            }
        }

        function renderVoiceApprovalCard(d) {
            const card = document.getElementById('voice-copilot-approval-card');
            const title = document.getElementById('voice-card-title');
            const total = document.getElementById('voice-card-total');
            const body = document.getElementById('voice-card-body');
            if (!card) return;

            if (title) title.textContent = d.title;
            if (total) total.textContent = d.total;

            if (d.type === 'sales') {
                body.innerHTML = `
                    <div><b>العميل:</b> ${d.partner}</div>
                    <div><b>الأصناف والكمية:</b> ${d.item}</div>
                    <div><b>السعر الفردي:</b> ${d.unitPrice}</div>
                    <div><b>المستودع والدفع:</b> ${d.warehouse} • نقداً</div>
                `;
            } else if (d.type === 'payment') {
                body.innerHTML = `
                    <div><b>الطرف المستفيد:</b> ${d.partner}</div>
                    <div><b>المبلغ:</b> ${d.amount}</div>
                    <div><b>الحساب المصروف منه:</b> ${d.account}</div>
                    <div><b>رقم القيد والبيان:</b> ${d.ref} • ${d.notes}</div>
                `;
            } else {
                body.innerHTML = `
                    <div><b>الطرف:</b> ${d.partner}</div>
                    <div><b>الرصيد القائم:</b> ${d.total}</div>
                `;
            }

            card.style.display = 'block';
        }

        function confirmVoiceCopilotTransaction() {
            triggerHaptic('heavy');
            playSoundEffect('cash');
            const d = currentVoiceCopilotData;
            if (!d) return;

            if (d.type === 'sales') {
                alert('✅ تم بنجاح اعتماد وترحيل الفاتورة #' + d.ref + ' للعميل [' + d.partner + ']!\nتم تحديث المخزون وقيد المبيعات فوراً.');
            } else if (d.type === 'payment') {
                alert('✅ تم بنجاح صرف مبلغ [' + d.amount + '] إلى [' + d.partner + '] برقم قيد ' + d.ref + '!\nتم خصم المبلغ من الخزينة الرئيسية.');
            } else {
                closeBottomSheet('sheet-ai-voice-copilot');
                switchMobileTab('ledgers');
                return;
            }

            closeBottomSheet('sheet-ai-voice-copilot');
            switchMobileTab('transactions');
        }

        function editVoiceCopilotTransaction() {
            closeBottomSheet('sheet-ai-voice-copilot');
            if (currentVoiceCopilotData && currentVoiceCopilotData.type === 'sales') {
                openBottomSheet('sheet-sales-suite');
            } else {
                openQuickCashPayment();
            }
        }

        function openTxAuditSettings(tx) {
            triggerHaptic('light');
            alert('⚙️ ضبط وتدقيق المعاملة #' + (tx.voucher_no || tx.id || '---') + '\nتم فتح نافذة الربط الضريبي وسجل مراجعة القيد المزدوج.');
        }

    

    // ═════════════════════════════════════════════════════════════════
    // 📊 BALANCES MODAL & OMNI SEARCH ENGINE ("الأرصدة" وكشف الحساب)
    // ═════════════════════════════════════════════════════════════════
    let currentNonZeroTab = 'all';
    let currentNonZeroSearch = '';
    let currentReportPeriodFilter = 'all';

    function openNonZeroBalancesSheet() {
        triggerHaptic('medium');
        const sheet = document.getElementById('sheet-balances-nonzero');
        if (sheet) sheet.classList.add('active');
        filterNonZeroBalances('all', '');
    }

    function closeNonZeroBalancesSheet() {
        triggerHaptic('light');
        const sheet = document.getElementById('sheet-balances-nonzero');
        if (sheet) sheet.classList.remove('active');
    }

    function filterNonZeroBalances(tabType, query) {
        if (tabType !== undefined) currentNonZeroTab = tabType;
        if (query !== undefined) currentNonZeroSearch = query;

        const tabs = {
            'all': document.getElementById('bal-tab-all'),
            'customer': document.getElementById('bal-tab-cust'),
            'supplier': document.getElementById('bal-tab-supp'),
            'cash': document.getElementById('bal-tab-cash')
        };
        Object.entries(tabs).forEach(([k, btn]) => {
            if (!btn) return;
            if (k === currentNonZeroTab) btn.classList.add('active');
            else btn.classList.remove('active');
        });

        const rate = (typeof currentUsdRate !== 'undefined' && currentUsdRate > 0) ? currentUsdRate : 2800;
        let accounts = [];

        // Aggregate Customers (Non-Zero)
        if (typeof M_CUSTOMERS !== 'undefined' && M_CUSTOMERS.length > 0) {
            M_CUSTOMERS.forEach(c => {
                const bal = parseFloat(c.balance || 0);
                if (bal !== 0) {
                    accounts.push({
                        id: c.id,
                        name: c.name,
                        category: 'customer',
                        typeLabel: 'عميل',
                        typeClass: 'badge-receivables',
                        balanceLocal: bal,
                        balanceUSD: Math.round(bal / rate),
                        nature: 'مدين (مطلوب سداده لنا)',
                        natureColor: '#fb7185'
                    });
                }
            });
        }

        // Aggregate Suppliers (Non-Zero)
        const supps = (typeof M_SUPPLIERS !== 'undefined' && M_SUPPLIERS.length > 0) ? M_SUPPLIERS : [
            { id: 'supp_1', name: 'مطاحن الخرطوم للغلال', balance: 51240000 },
            { id: 'supp_2', name: 'مصانع سيقا للزيوت', balance: 38780000 },
            { id: 'supp_3', name: 'مصنع أسمنت بربر', balance: 16240000 }
        ];
        supps.forEach(s => {
            const bal = parseFloat(s.balance || 0);
            if (bal !== 0) {
                accounts.push({
                    id: s.id,
                    name: s.name,
                    category: 'supplier',
                    typeLabel: 'مورد',
                    typeClass: 'badge-payable',
                    balanceLocal: bal,
                    balanceUSD: Math.round(bal / rate),
                    nature: 'دائن (له مستحقات علينا)',
                    natureColor: '#38bdf8'
                });
            }
        });

        // Aggregate Cash & Banks (Non-Zero)
        const vaults = (typeof M_VAULTS !== 'undefined' && M_VAULTS.length > 0) ? M_VAULTS : [
            { id: 'v_1', name: 'الخزينة الرئيسية (الإدارة)', balance: 25060000, type: 'خزينة' },
            { id: 'v_2', name: 'بنك الخرطوم (الحساب الجاري)', balance: 79520000, type: 'بنك' },
            { id: 'v_3', name: 'بنك فيصل الإسلامي', balance: 60200000, type: 'بنك' }
        ];
        vaults.forEach(v => {
            const bal = parseFloat(v.balance || 0);
            if (bal !== 0) {
                accounts.push({
                    id: v.id,
                    name: v.name,
                    category: 'cash',
                    typeLabel: v.type || 'نقدية',
                    typeClass: 'badge-cash',
                    balanceLocal: bal,
                    balanceUSD: Math.round(bal / rate),
                    nature: 'رصيد نقدية متاح',
                    natureColor: '#34d399'
                });
            }
        });

        // Filter by tab
        let filtered = accounts;
        if (currentNonZeroTab === 'customer') filtered = filtered.filter(a => a.category === 'customer');
        else if (currentNonZeroTab === 'supplier') filtered = filtered.filter(a => a.category === 'supplier');
        else if (currentNonZeroTab === 'cash') filtered = filtered.filter(a => a.category === 'cash');

        // Filter by search query
        if (currentNonZeroSearch && currentNonZeroSearch.trim()) {
            const q = currentNonZeroSearch.trim().toLowerCase();
            filtered = filtered.filter(a => a.name.toLowerCase().includes(q) || a.typeLabel.toLowerCase().includes(q));
        }

        const container = document.getElementById('nonzero-balances-container');
        if (!container) return;

        if (filtered.length === 0) {
            container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-muted); font-size:0.84rem; font-weight:800;">لا توجد حسابات نشطة تطابق البحث</div>';
            return;
        }

        container.innerHTML = filtered.map(acc => {
            const sdgFormatted = fmt(acc.balanceLocal) + ' SDG';
            const usdFormatted = '$' + fmt(acc.balanceUSD) + ' USD';
            return `
                <div style="background:var(--surface-sub); border:1.5px solid var(--border-glass); border-radius:16px; padding:12px 14px; display:flex; flex-direction:column; gap:10px;">
                    <div style="display:flex; justify-content:space-between; align-items:center;">
                        <div style="display:flex; align-items:center; gap:8px;">
                            <strong style="color:#fff; font-size:0.92rem;">${acc.name}</strong>
                            <span style="font-size:0.72rem; padding:2px 8px; border-radius:6px; background:rgba(255,255,255,0.08); color:var(--text-main); font-weight:800;">${acc.typeLabel}</span>
                        </div>
                        <span style="font-size:0.70rem; color:${acc.natureColor}; font-weight:800; border:1px solid ${acc.natureColor}40; background:${acc.natureColor}15; padding:2px 8px; border-radius:12px;">${acc.nature}</span>
                    </div>

                    <!-- Dual Currency Highlight (Bold SDG & Bold USD with beautiful colors) -->
                    <div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">
                        <div style="background:rgba(245,158,11,0.15); border:1px solid rgba(245,158,11,0.4); border-radius:10px; padding:8px; text-align:right;">
                            <span style="font-size:0.68rem; color:#fbbf24; font-weight:800; display:block; margin-bottom:2px;">🇸🇩 العملة المحلية:</span>
                            <span style="font-size:0.95rem; font-weight:900; color:#fbbf24; font-family:'Inter', sans-serif;">${sdgFormatted}</span>
                        </div>
                        <div style="background:rgba(16,185,129,0.15); border:1px solid rgba(16,185,129,0.4); border-radius:10px; padding:8px; text-align:right;">
                            <span style="font-size:0.68rem; color:#34d399; font-weight:800; display:block; margin-bottom:2px;">💵 المعادل بالدولار:</span>
                            <span style="font-size:0.95rem; font-weight:900; color:#34d399; font-family:'Inter', sans-serif;">${usdFormatted}</span>
                        </div>
                    </div>

                    <!-- Action Buttons -->
                    <div style="display:flex; gap:8px; justify-content:flex-end; border-top:1px solid rgba(255,255,255,0.05); padding-top:8px;">
                        <button type="button" onclick="viewStatementFromBalances('${acc.id}', '${acc.category}', '${acc.name}')" style="flex:1; background:linear-gradient(135deg, #06b6d4, #0891b2); color:#fff; border:none; border-radius:10px; padding:8px 12px; font-size:0.78rem; font-weight:900; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:6px;">
                            <i class="fa-solid fa-file-invoice"></i> كشف الحساب (كل الفترة)
                        </button>
                        <button type="button" onclick="shareBalanceWhatsAppDirect('${acc.name}', '${sdgFormatted}', '${usdFormatted}')" style="background:#22c55e; color:#fff; border:none; border-radius:10px; padding:8px 14px; font-size:0.78rem; font-weight:900; cursor:pointer;">
                            <i class="fa-brands fa-whatsapp"></i>
                        </button>
                    </div>
                </div>
            `;
        }).join('');
    }

    function viewStatementFromBalances(accId, category, name) {
        closeNonZeroBalancesSheet();
        if (category === 'customer' || category === 'supplier') {
            switchMobileTab('ledgers');
            if (typeof LedgerEngine !== 'undefined') {
                LedgerEngine.setPartyType(category);
                LedgerEngine.selectParty(accId);
                // Guaranteed default to 'all' ("كل الفترة")
                LedgerEngine.setDateFilter('all');
            }
        } else {
            // Cash / Vault / Bank statement
            renderReportStatement(accId);
            const res = document.getElementById('report-statement-result');
            if (res) res.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
    }

    function shareBalanceWhatsAppDirect(name, sdgFormatted, usdFormatted) {
        const text = encodeURIComponent(`*إشعار رصيد معتمد - شركة السجانة*\nالحساب: ${name}\nالمبلغ: ${sdgFormatted} (ما يعادل ${usdFormatted})\nتاريخ الاستخراج: 2026-10-04`);
        window.open(`https://wa.me/?text=${text}`, '_blank');
    }

    // Omni Search functions
    function onOmniKashfSearch(query) {
        const drop = document.getElementById('omni-kashf-suggestions');
        const q = query.trim().toLowerCase();
        if (!q) {
            if (drop) drop.style.display = 'none';
            return;
        }
        const rate = (typeof currentUsdRate !== 'undefined' && currentUsdRate > 0) ? currentUsdRate : 2800;
        let pool = [];
        if (typeof M_CUSTOMERS !== 'undefined') {
            M_CUSTOMERS.forEach(c => pool.push({ id: c.id, name: c.name, type: 'عميل', category: 'customer', balance: c.balance || 0 }));
        }
        if (typeof M_SUPPLIERS !== 'undefined') {
            M_SUPPLIERS.forEach(s => pool.push({ id: s.id, name: s.name, type: 'مورد', category: 'supplier', balance: s.balance || 0 }));
        }
        if (typeof M_VAULTS !== 'undefined') {
            M_VAULTS.forEach(v => pool.push({ id: v.id, name: v.name, type: v.type || 'خزينة', category: 'cash', balance: v.balance || 0 }));
        }

        const matches = pool.filter(p => p.name.toLowerCase().includes(q));
        if (matches.length === 0) {
            drop.innerHTML = '<div style="padding:8px; text-align:center; color:var(--text-muted); font-size:0.78rem;">لا توجد نتائج مطابقة</div>';
        } else {
            drop.innerHTML = matches.map(m => `
                <div onclick="selectOmniAccount('${m.id}', '${m.category}', '${m.name}')" style="padding:8px 10px; border-radius:10px; cursor:pointer; display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid rgba(255,255,255,0.05); font-size:0.80rem;">
                    <div>
                        <strong style="color:#fff;">${m.name}</strong>
                        <span style="font-size:0.70rem; color:var(--text-muted); margin-right:4px;">(${m.type})</span>
                    </div>
                    <span style="color:#fbbf24; font-weight:800; font-family:'Inter', sans-serif;">${fmt(m.balance)} SDG</span>
                </div>
            `).join('');
        }
        drop.style.display = 'block';
    }

    function selectOmniAccount(id, category, name) {
        const inp = document.getElementById('omni-search-kashf');
        if (inp) inp.value = name;
        const drop = document.getElementById('omni-kashf-suggestions');
        if (drop) drop.style.display = 'none';

        if (category === 'customer' || category === 'supplier') {
            setReportStatementType(category);
            const sel = document.getElementById('report-statement-select');
            if (sel) sel.value = id;
            renderReportStatement(id);
        }
    }

    function triggerKashfViewFromOmni() {
        const inp = document.getElementById('omni-search-kashf');
        const q = (inp ? inp.value : '').trim();
        if (!q && typeof M_CUSTOMERS !== 'undefined' && M_CUSTOMERS.length > 0) {
            renderReportStatement(M_CUSTOMERS[0].id);
            return;
        }
        // Match account
        let match = null;
        if (typeof M_CUSTOMERS !== 'undefined') match = M_CUSTOMERS.find(c => c.name.includes(q));
        if (!match && typeof M_SUPPLIERS !== 'undefined') match = M_SUPPLIERS.find(s => s.name.includes(q));
        if (match) {
            renderReportStatement(match.id);
        } else if (typeof M_CUSTOMERS !== 'undefined' && M_CUSTOMERS.length > 0) {
            renderReportStatement(M_CUSTOMERS[0].id);
        }
    }

    function setReportPeriod(periodKey, btn) {
        currentReportPeriodFilter = periodKey;
        document.querySelectorAll('#report-statement-result .date-pill').forEach(p => p.classList.remove('active'));
        if (btn) btn.classList.add('active');
        const badge = document.getElementById('rep-stmt-period-badge');
        const names = {
            'all': '✓ كل الفترة (افتراضي)',
            'today': 'اليوم فقط',
            'week': 'هذا الأسبوع',
            'month': 'هذا الشهر',
            'custom': 'نطاق مخصص'
        };
        if (badge && names[periodKey]) badge.textContent = names[periodKey];
    }

</script>

    <!-- ═════════════════════════════════════════════════════════════════
         BOTTOM SHEET: 📊 ميزان الأرصدة الحية (الحسابات غير الصفرية فقط)
         ═════════════════════════════════════════════════════════════════ -->
    <div class="m-sheet" id="sheet-balances-nonzero" style="z-index:9999;">
        <div class="m-sheet-scrim" onclick="closeNonZeroBalancesSheet()"></div>
        <div class="m-sheet-panel" style="max-height:85vh; border-radius:24px 24px 0 0; background:#0f172a; border-top:2px solid #10b981;">
            <div class="m-sheet-handle"></div>
            <div class="m-sheet-header" style="border-bottom:1px solid rgba(255,255,255,0.08); padding-bottom:10px;">
                <div style="display:flex; justify-content:space-between; align-items:center;">
                    <div style="display:flex; align-items:center; gap:8px;">
                        <div style="width:36px; height:36px; border-radius:10px; background:rgba(16,185,129,0.2); color:#10b981; display:flex; align-items:center; justify-content:center;">
                            <i class="fa-solid fa-scale-balanced" style="font-size:1.1rem;"></i>
                        </div>
                        <div>
                            <h3 style="margin:0; font-size:1rem; font-weight:900; color:#fff;">ميزان الأرصدة الحية (غير الصفرية)</h3>
                            <span style="font-size:0.72rem; color:#34d399; font-weight:700;">الحسابات التي بها رصيد بالعملة المحلية وبالدولار</span>
                        </div>
                    </div>
                    <button type="button" class="m-sheet-close" onclick="closeNonZeroBalancesSheet()" style="background:rgba(255,255,255,0.08); border:none; color:#94a3b8; width:32px; height:32px; border-radius:50%; cursor:pointer;">✕</button>
                </div>

                <!-- Instant Search input in Sheet -->
                <div style="margin-top:10px;">
                    <input type="text" id="sheet-bal-search-input" class="m-input" placeholder="بحث سريع في الحسابات والأرصدة..." style="height:38px; font-size:0.82rem; border-radius:10px;" oninput="filterNonZeroBalances(currentNonZeroTab, this.value)">
                </div>

                <!-- Category Tabs -->
                <div style="display:flex; gap:6px; overflow-x:auto; margin-top:8px;" class="no-scrollbar">
                    <button type="button" class="btn-ai-chip active" id="bal-tab-all" onclick="filterNonZeroBalances('all')" style="font-size:0.75rem; padding:4px 10px;">الكل</button>
                    <button type="button" class="btn-ai-chip" id="bal-tab-cust" onclick="filterNonZeroBalances('customer')" style="font-size:0.75rem; padding:4px 10px;">عملاء (مدين)</button>
                    <button type="button" class="btn-ai-chip" id="bal-tab-supp" onclick="filterNonZeroBalances('supplier')" style="font-size:0.75rem; padding:4px 10px;">موردين (دائن)</button>
                    <button type="button" class="btn-ai-chip" id="bal-tab-cash" onclick="filterNonZeroBalances('cash')" style="font-size:0.75rem; padding:4px 10px;">خزن وبنوك</button>
                </div>
            </div>

            <div class="m-sheet-body" style="padding:12px; overflow-y:auto; max-height:calc(85vh - 160px);">
                <div id="nonzero-balances-container" style="display:flex; flex-direction:column; gap:10px;">
                    <!-- Rendered Dynamically -->
                </div>
            </div>
        </div>
    </div>

</body>
</html>
